const e="WADA Prohibited List (World Anti-Doping Agency), current edition.",i="U.S. FDA. Bulk drug substances nominated for use in compounding under section 503B — Category 2 (substances that raise significant safety risks), entry dated 29 September 2023; list updated 21 March 2025.",s="U.S. FDA. Safety risks associated with certain bulk drug substances nominated for use in compounding — table of withdrawn nominations (page current 22 April 2026).",r=Object.freeze({id:"peptide",label:"Peptides & research compounds",short:"Peptides & SARMs",icon:"🧪"}),o=[{id:"trt",name:"Testosterone (TRT and higher doses)",category:"prescription",rx:!0,exogenousT:!0,evidence:"strong",status:"Prescription only (Schedule III). Replacement is for diagnosed hypogonadism; doses above replacement are not an approved use. WADA prohibited.",summary:"Testosterone's effect on lean mass rises with the blood level. Bhasin's trials show fat-free mass going up roughly in step with the log of serum T, from low levels to about 2,400 ng/dL, even without training. Lifting adds to that. Forge uses your on-therapy blood level (or estimates it from your dose) against your own natural level.",mechanism:"Androgen receptor activation raises muscle protein synthesis and satellite-cell activity. Higher serum T means more lean mass, with no clear plateau inside the studied range, and fat mass falls at higher levels.",effects:["Bhasin 1996 (600 mg/wk, 10 wk): fat-free mass +6.1 kg with lifting, +3.2 kg without, vs +1.9 kg for lifting on placebo.","Bhasin 2001 (20 wk, no training): ≈ −0.3 kg at ~250 ng/dL, ~0 at ~300, +3.4 kg at ~540, +5.2 kg at ~1,350, +7.9 kg at ~2,400.","Forge: direct (training-independent) lean from log(on-therapy T ÷ your natural T), mostly in the first ~20 weeks, then it levels off. The training ceiling rises modestly with log T above natural (the extra +1 kg in Bhasin 1996).","Above ~2,400 ng/dL (the highest studied level) the effect plateaus; Forge does not extrapolate."],risks:["Shuts down your own testosterone and sperm production (HPTA suppression). Infertility is common while on it; in WHO contraception trials ~200 mg/week made most men azoospermic. Recovery after stopping can take months.","Raises hematocrit (thicker blood), more so at higher levels; needs regular blood counts.","Monitoring: total T, hematocrit, PSA, lipids, blood pressure.","TRAVERSE (2023): no rise in major cardiac events on replacement in older hypogonadal men, but more atrial fibrillation, pulmonary embolism and kidney injury."],typicalUse:"Physician-prescribed replacement (e.g. weekly or biweekly injections, gels) titrated to a mid-normal level on follow-up labs",sources:["Bhasin S, et al. The effects of supraphysiologic doses of testosterone on muscle size and strength in normal men. N Engl J Med. 1996;335(1):1-7.","Bhasin S, et al. Testosterone dose-response relationships in healthy young men. Am J Physiol Endocrinol Metab. 2001;281(6):E1172-E1181.","Bhasin S, et al. Testosterone replacement increases fat-free mass and muscle size in hypogonadal men. J Clin Endocrinol Metab. 1997;82(2):407-413.","Bhasin S, et al. Older men are as responsive as young men to the anabolic effects of graded doses of testosterone on the skeletal muscle. J Clin Endocrinol Metab. 2005;90(2):678-688.","Bhasin S, et al. Testosterone therapy in men with hypogonadism: an Endocrine Society clinical practice guideline. J Clin Endocrinol Metab. 2018;103(5):1715-1744.","Lincoff AM, et al. Cardiovascular safety of testosterone-replacement therapy (TRAVERSE). N Engl J Med. 2023;389(2):107-117.","World Health Organization Task Force on Methods for the Regulation of Male Fertility. Contraceptive efficacy of testosterone-induced azoospermia in normal men. Lancet. 1990;336(8721):955-959.","Travison TG, et al. Harmonized reference ranges for circulating testosterone levels in men of four cohort studies in the United States and Europe. J Clin Endocrinol Metab. 2017;102(4):1161-1173.","Morton RW, et al. Muscle androgen receptor content but not systemic hormones is associated with resistance training-induced skeletal muscle hypertrophy in healthy, young men. Front Physiol. 2018;9:1373."],model:{kind:"testosterone",requiresLab:"totalT",dose:{unit:"mg/week",default:100,label:"studied replacement dose (Bhasin 1997)",studied:[25,600],note:"Testosterone enanthate/cypionate. The dose is only used to estimate your level when no on-therapy lab is entered."},doseToLevel:[[0,0],[25,253],[50,306],[125,542],[300,1345],[600,2370]],rampWeeks:20,leanCeilingMult:1.06,leanDirectLbPerWeek:.17,fatDirectLbPerWeek:-.05,levelRisks:[{min:1,text:"Any exogenous testosterone suppresses natural production and sperm count. If fertility matters, talk to your physician about it first (hCG and other options exist)."},{min:900,text:"Upper-normal and above: hematocrit rises with level; above ~54% the dose usually gets reduced (Endocrine Society)."},{min:1100,text:'Above the normal range: HDL ("good") cholesterol falls with dose (significant at 300–600 mg/wk in Bhasin 2001); acne, oily skin, raised blood pressure and breast tenderness or gynecomastia (from conversion to estradiol) become more common.'},{min:2e3,text:"Near the top of the studied range: in older men on the highest doses (Bhasin 2005), adverse events including hematocrit above 54% were more frequent."}]}},{id:"clomiphene",name:"Clomiphene citrate (off-label)",category:"prescription",rx:!0,evidence:"moderate",status:"Prescription only; used off-label in men (FDA-approved only for ovulation induction in women). WADA prohibited (S4 hormone and metabolic modulators).",summary:"The best-evidenced way to raise your OWN testosterone. In men with low testosterone and a pituitary that still works, a meta-analysis of 10 randomized trials found +274 ng/dL versus placebo, with LH and FSH going up rather than down — so sperm production is preserved, unlike with testosterone therapy. It also works in men whose testosterone is already normal: in healthy men aged 26–33 it took the group mean from 519 to 1,390 ng/dL. What is NOT known is whether that extra testosterone, made by your own testes, builds muscle the way injected testosterone does. Nobody has measured it.",mechanism:"Blocks estrogen receptors in the hypothalamus and pituitary, so the brain stops seeing the negative feedback, releases more LH and FSH, and your own testes make more testosterone. Estradiol rises along with it.",effects:["Hohl 2025 meta-analysis (10 RCTs, 819 men with functional or secondary hypogonadism, baseline 67–303 ng/dL): total T +273.8 ng/dL (95% CI 191.9–355.7, I²=89%), LH +4.66 IU/L (3.37–5.94), FSH +4.59 IU/L (2.88–6.30), free T SMD 1.57 (0.44–2.70), DHT +7.58 ng/dL (3.42–11.73), estradiol +33.99 pg/mL (19.19–48.79). GRADE moderate. The benefit shrank with higher age (p=0.043) and higher BMI (p=0.0008).",'IMPORTANT ABOUT THAT +274 (corrected 2026-10-20): Hohl pooled clomiphene AND enclomiphene together as one "SERM" class — the 10 trials include Kim 2016 and both Wiehle 2014 studies. It is a class estimate, not a clomiphene-specific one, and Forge now says so. The clomiphene-SPECIFIC pooled figure is higher: Tienforti 2023 pooled the isomers separately in obesity-related androgen deficiency and got clomiphene +11.56 nmol/L ≈ +333 ng/dL (95% CI 9.68–13.43) against enclomiphene +7.50 ≈ +216. Forge keeps its curve anchored on 274 anyway, because that is the more conservative of the two and it is the one with the wider population behind it.',"SHBG did NOT move significantly in the pooled analysis (+3.63 nmol/L, 95% CI −0.54 to 7.81, p=0.09), although the single body-composition trial (Soares 2018) did report a rise.","Equal to testosterone gel on serum levels (difference 5.41 ng/dL, 95% CI −43 to +54). Hohl 2025 did not compare SERMs with injections, so Forge makes no claim there.","Fertility is the real differentiator: SERMs kept sperm concentration 70.4 million/mL higher than gel (95% CI 41.6–99.2), and the risk of falling below 15 million/mL was 90% lower (RR 0.10).","IT WORKS IN MEN WITH A NORMAL TESTOSTERONE TOO — the single biggest correction in this entry. Tenover & Bremner 1991 (J Androl 12:258–63, PMID 1917692) gave 50 mg twice daily for 8 weeks to five HEALTHY men aged 26–33 (baseline 18.0 ± 1.0 nmol/L = 519 ng/dL, screened for normal testes, normal weight, non-smokers, no medication): the group mean reached 48.2 ± 1.4 nmol/L = 1,390 ng/dL, 2.7× baseline. Five healthy men aged 65–85 (baseline 499 ng/dL) reached 34.3 nmol/L = 989 ng/dL, 2.0× baseline — the young men responded significantly more.","Bremner/Tenover 1987 (JCEM 65:1118–26, doi:10.1210/jcem-65-6-1118) is the larger version: 14 healthy men aged 22–35 and 14 aged 65–84, same 100 mg/day dose, only 7 days. 24-hour mean total T 4.9 → 9.8 ng/mL (490 → 980 ng/dL, +100%) in the young men and 4.1 → 5.4 ng/mL (410 → 540, +34%) in the elderly. Estradiol 37 → 54 pg/mL (young) and 37 → 47 (elderly). SHBG 24.5 → 31.3 nmol/L (young, +28%) and 31.0 → 40.0 (elderly, +29%).","And free testosterone goes up with it. In those same young men, non-SHBG-bound T by the Södergard formula went 3.2 → 6.5 ng/mL, which is 65% → 66% of total: the bioavailable FRACTION did not change, so free T rose in proportion to total. Soares 2018 measured free T rising (p<0.001) in obese hypogonadal men even though SHBG rose; Guay 1995 (double-blind, placebo-controlled crossover) and Guay 2003 (n=178) both found free T up significantly on clomiphene.",'A raised LH does NOT rule you out. Keihani 2020 (Urology 142:119–24, doi:10.1016/j.urology.2020.04.074; 332 men, mean age 36.2) found total T rose +329 ng/dL (95% CI 307–351), 73% of men gained at least 200 ng/dL, and NEITHER baseline LH NOR FSH predicted the response: "adequate biochemical response ... can be expected in most patients with normal or slightly elevated baseline gonadotropin levels." Patel 2015 and Roque 2026 agree. Kim 2026 (n=292) did find higher LH predicted worse response, but as a gradient (OR 0.82 per mIU/mL), not a cliff.',"Age is the thing that actually shrinks the response — not your starting level. Tenover: young > elderly in both papers. Hohl 2025: benefit fell with age (p=0.043) and BMI (p=0.0008). Guay 2003: response fell significantly with age (p<0.05). Keihani 2020: age was the only significant univariable predictor. Both Keihani and Kim found baseline total T was NOT predictive.","Dose: there is no within-trial dose ladder for clomiphene in men. 25 mg/day took 36 men from 247.6 ± 39.8 to 610.0 ± 178.6 ng/dL in 4–6 weeks (Shabsigh 2005), which is indistinguishable from the 50 mg/day trials, so the curve looks close to flat across 25–50 mg. The 1,390 ng/dL figure comes from 100 mg/day, two to four times the usual clinical dose.","Body composition: only one trial has ever measured it. Soares 2018 (RCT, 78 men with obesity, BMI >30, baseline 226 ± 70 ng/dL, 50 mg/day, 12 weeks) found improved lean mass (p<0.001), fat-free mass (p=0.004) and muscle mass (p<0.001) — but by bioimpedance, not DXA, and only in obese men with low T. HDL fell (p<0.001). Nothing has been measured in a man with a normal testosterone.","No glucose or weight benefit: FBG, HbA1c, insulin and BMI were all unchanged vs placebo (Hohl 2025).","Forge models the testosterone rise at ANY baseline, because that is what was measured. It credits muscle as MEASURED only up to about 500 ng/dL (where Soares landed) and as an EXTRAPOLATION above that, with a range that starts at zero."],risks:["Mood changes, blurred or flickering vision (stop and call your doctor), breast tenderness; 8% of men reported a side effect in the longest series (Krzastek 2019, 120 men followed past 3 years). See the tolerability block for the itemised rates.","Estradiol rises, which is part of how it works but can cause breast tenderness or gynecomastia.",'HDL ("good") cholesterol fell significantly in the one trial that measured body composition (Soares 2018, p<0.001). Enclomiphene did not do this in the trial that looked (Wiehle 2013, p=0.78), and in baboons the two isomers moved cholesterol in opposite directions, so this looks like a zuclomiphene effect.',"In the only head-to-head, the same men reported side effects far more often on clomiphene than after switching to enclomiphene — 47% vs 13.8%, driven by low libido, low energy and mood (Saffati 2024). That study is retrospective and unblinded, but it is the only direct comparison that exists.","Libido was lower on clomiphene than on testosterone therapy in a meta-analysis (−0.54, 95% CI −0.87 to −0.21).",'It needs testes that can respond to the signal. A clearly raised LH together with a low testosterone means the signal is already maximal and is not being acted on ("primary"), and then this is the wrong tool — it works by raising LH further. You cannot tell that by looking: the testosterone-making Leydig cells are a small part of testis volume, so they can be failing at normal size, and the usual causes are age-related Leydig decline, a past varicocele, mumps orchitis, trauma or chemotherapy. A normal or slightly raised LH is not a reason to rule it out (Keihani 2020), and a raised LH with a still-normal testosterone ("compensated", Tajar 2010) is not either.',"Using it in a man whose testosterone is already normal has no outcome data at all. The hormone moves; whether anything else does is unmeasured, and the only long-term safety data in men are retrospective series in hypogonadal patients.","Long-term safety data come from retrospective series, not trials; one 400-man series followed men for an average of about two years with 88% reaching normal levels."],typicalUse:"Off-label, prescribed and monitored by a urologist or endocrinologist for secondary hypogonadism, especially when fertility matters. Your prescriber sets the dose and schedule and follows total T, estradiol, hematocrit and PSA.",sources:["Hohl A, et al. Clomiphene or enclomiphene citrate for the treatment of male hypogonadism: a systematic review and meta-analysis of randomized controlled trials. Arch Endocrinol Metab. 2025;69(5):e250093. doi:10.20945/2359-4292-2025-0093 — NOTE: pools clomiphene and enclomiphene together as one SERM class.","Tienforti D, et al. Selective modulation of estrogen receptor in obese men with androgen deficiency: a systematic review and meta-analysis. Andrology. 2023;11(6):1067-1076. doi:10.1111/andr.13373 — pools the two isomers SEPARATELY: clomiphene +333 ng/dL, enclomiphene +216.","Soares AH, et al. Effects of clomiphene citrate on male obesity-associated hypogonadism: a randomized, double-blind, placebo-controlled study. Int J Obes. 2018;42(5):953-963. doi:10.1038/s41366-018-0105-2","Guo DP, Zlatev DV, Li S, Baker LC, Eisenberg ML. Demographics, usage patterns, and safety of male users of clomiphene in the United States. World J Mens Health. 2020;38(2):220-225. doi:10.5534/wjmh.190028","Saffati G, et al. Safety and efficacy of enclomiphene and clomiphene for hypogonadal men. Transl Androl Urol. 2024;13(9):1984-1990. doi:10.21037/tau-24-238","Ramasamy R, et al. Testosterone supplementation versus clomiphene citrate for hypogonadism: an age matched comparison of satisfaction and efficacy. J Urol. 2014;192(3):875-879.","Krzastek SC, et al. Long-term safety and efficacy of clomiphene citrate for the treatment of hypogonadism. J Urol. 2019;202(5):1029-1035. doi:10.1097/JU.0000000000000396 — 400 men, mean 25.5 months, to 7 years.","Mulhall JP, et al. Evaluation and management of testosterone deficiency: AUA guideline. J Urol. 2018;200(2):423-432.","Tenover JS, Bremner WJ. The effects of normal aging on the response of the pituitary-gonadal axis to chronic clomiphene administration in men. J Androl. 1991;12(4):258-263. PMID 1917692.","Bremner WJ, Plymate SR, Tenover JS, Matsumoto AM. The effects of aging in normal men on bioavailable testosterone and luteinizing hormone secretion: response to clomiphene citrate. J Clin Endocrinol Metab. 1987;65(6):1118-1126. doi:10.1210/jcem-65-6-1118","Keihani S, et al. Baseline gonadotropin levels and testosterone response in hypogonadal men treated with clomiphene citrate. Urology. 2020;142:119-124. doi:10.1016/j.urology.2020.04.074","Shabsigh A, et al. Clomiphene citrate effects on testosterone/estrogen ratio in male hypogonadism. J Sex Med. 2005;2(5):716-721. doi:10.1111/j.1743-6109.2005.00075.x","Guay AT, et al. Clomiphene increases free testosterone levels in men with both secondary hypogonadism and erectile dysfunction: who does and does not benefit? Int J Impot Res. 2003;15(3):156-165. doi:10.1038/sj.ijir.3900981","Kim DJ, et al. Predictors of clomiphene citrate response in the treatment of men with testosterone deficiency. J Sex Med. 2026;23(7). doi:10.1093/jsxmed/qdag159","Mazzola CR, et al. Predicting biochemical response to clomiphene citrate in men with hypogonadism. J Sex Med. 2014;11(9):2302-2307. doi:10.1111/jsm.12592","Tajar A, et al. Characteristics of secondary, primary, and compensated hypogonadism in aging men: evidence from the European Male Ageing Study. J Clin Endocrinol Metab. 2010;95(4):1810-1818. doi:10.1210/jc.2009-1796",e],model:{kind:"tEndogenous",dose:{unit:"% of the studied regimen",default:100,label:"as studied (prescriber-set dose)",studied:[0,100],note:"Forge models the trial-average response, not a dose you choose."},response:[[0,0],[100,1]],tPctByBaseline:[[150,183],[200,137],[250,110],[300,91],[350,78],[400,69],[450,61],[500,55],[550,50],[650,41],[800,31],[1e3,22]],rampWeeks:6,maxLevel:1390,axis:"serm",ceilingNg:1390,tCI:[.7,1.3],e2Pct:90,e2ActionPct:90,shbgDelta:4,e2Note:"Estradiol rises a lot (+34 pg/mL pooled, 95% CI 19–49). That is part of the mechanism, not a side-show. Forge does NOT turn a SERM's serum-E2 rise into fat loss: Finkelstein's fat finding is about estrogen ACTION, and a SERM raises the hormone while blocking the receptor in some tissues. Direction unknown, so zero.",shbgNote:"SHBG rises a little and early and then settles: +28% after 7 days in healthy young men (Bremner 1987, 24.5 → 31.3 nmol/L), no significant change at all after 8 weeks (Tenover 1991), +3.63 nmol/L and not significant in the pooled analysis (Hohl 2025, p=0.09). Forge models +4 nmol/L. Crucially the bioavailable FRACTION did not fall: 65% → 66% of total in Bremner 1987, so free testosterone rose in proportion to total.",tolerability:{grade:"moderate",comparedWith:"placebo in randomized trials; its own pre-treatment rate in a 12,318-man claims cohort; enclomiphene in one retrospective within-patient comparison",evidence:"rct",headline:"Hard endpoints are reassuring at scale; symptom side effects are common — 47% in the one study that compared it directly with enclomiphene.",discontinuation:{pct:0,n:0,of:39,note:"No withdrawals for an adverse event in the clomiphene arm of the only placebo-controlled body-composition trial; the two withdrawals in that study were both in the PLACEBO arm. Separately, 63% of men in a 12,318-man claims cohort stopped within 6 months, but that database does not record why, and the commonest reasons are likely to be pregnancy achieved or no perceived benefit rather than toxicity.",source:"Soares 2018; Guo 2019"},events:[{label:"Any side effect, long-term use",pct:8,n:10,of:120,arm:"men treated longer than 3 years (mean 52 months)",p:"no significant adverse event occurred in any of the 400 patients",source:"Krzastek 2019"},{label:"Mood changes, long-term use",pct:4.2,n:5,of:120,arm:">3 years",source:"Krzastek 2019"},{label:"Blurred vision, long-term use",pct:2.5,n:3,of:120,arm:">3 years",p:"the classic SERM warning: it is a reason to stop and call the prescriber, not to wait",source:"Krzastek 2019"},{label:"Breast tenderness, long-term use",pct:1.7,n:2,of:120,arm:">3 years",source:"Krzastek 2019"},{label:"Any adverse event (vs enclomiphene, same patients)",pct:47,n:31,of:66,arm:"clomiphene",vs:{pct:13.8,n:8,of:58,label:"enclomiphene"},p:"0.001 (OR 0.18 in favour of enclomiphene, 95% CI 0.07–0.44)",source:"Saffati 2024"},{label:"Decreased libido",pct:33.3,n:22,of:66,arm:"clomiphene",vs:{pct:8.6,n:5,of:58,label:"enclomiphene"},p:"0.001",source:"Saffati 2024"},{label:"Erectile dysfunction",pct:18.2,n:12,of:66,arm:"clomiphene",vs:{pct:8.6,n:5,of:58,label:"enclomiphene"},p:"0.12 — not significant",source:"Saffati 2024"},{label:"Mood changes",pct:9.1,n:6,of:66,arm:"clomiphene",vs:{pct:0,n:0,of:58,label:"enclomiphene"},p:"0.03",source:"Saffati 2024"},{label:"Gynecomastia",pct:3,n:2,of:66,arm:"clomiphene",vs:{pct:0,n:0,of:58,label:"enclomiphene"},p:"0.49 — not significant",source:"Saffati 2024"},{label:"Somnolence",pct:12.8,n:5,of:39,arm:"clomiphene",vs:{pct:0,n:0,of:39,label:"placebo"},p:"0.064 — borderline",source:"Soares 2018"},{label:"HDL cholesterol",pct:null,n:null,of:39,arm:"FELL significantly vs placebo over 12 weeks",p:"<0.001 — the clearest measured harm on this drug",source:"Soares 2018"},{label:"Hematocrit",pct:null,n:null,of:39,arm:"no significant change vs placebo (p=0.409); median change +0.4% over a median 18.7 months in the head-to-head cohort",source:"Soares 2018; Saffati 2024"},{label:"PSA",pct:null,n:null,of:39,arm:"rose from 0.62 ± 0.41 to 0.76 ± 0.48 ng/mL, significant but inside the normal range; prostate symptom score unchanged (p=0.312)",p:"0.023",source:"Soares 2018"},{label:"Thrombotic events, vision problems, liver disease, nausea",pct:null,n:null,of:5118,arm:"no increase in the 6 months after starting vs the 6 months before, in US insurance claims",p:"gynecomastia, mental disorders, skin disorders and hypertension were all coded LESS often after starting, on low event counts",source:"Guo 2019, 12,318 men (5,118 with adequate follow-up)"},{label:"Venous thromboembolism and myocardial infarction",pct:null,n:null,of:null,arm:"case reports only (an isolated cortical vein thrombosis, a thrombotic STEMI in a man in his early 30s with no risk factors); no excess in the 5,118-man claims analysis",p:"a signal worth knowing about, not a measured rate",source:"Choi 2020; Shahid 2025; Guo 2019"},{label:"Bone mineral density",pct:null,n:null,of:null,arm:"not measured in men on clomiphene",p:"contrast: an aromatase inhibitor LOWERED spine BMD in a year-long randomized trial, which is why that item is graded poor and this one is not",source:"no study"}],note:'Two different questions with two different answers. "Is it dangerous?" — the evidence says no: 400 men followed to 7 years with no significant adverse event, 12,318 men in claims data with no excess thrombosis, eye disease or liver disease, and no adverse-event withdrawals in the placebo-controlled trial. "Does it make men feel worse?" — often enough to matter: a third reported low libido in the head-to-head cohort, and a meta-analysis found libido lower on clomiphene than on testosterone therapy (−0.54, 95% CI −0.87 to −0.21). The HDL fall is the one measured biochemical harm. All of the symptom comparisons against enclomiphene come from a single unblinded retrospective study.',sources:["Krzastek SC, et al. Long-term safety and efficacy of clomiphene citrate for the treatment of hypogonadism. J Urol. 2019;202(5):1029-1035. doi:10.1097/JU.0000000000000396","Guo DP, Zlatev DV, Li S, Baker LC, Eisenberg ML. Demographics, usage patterns, and safety of male users of clomiphene in the United States. World J Mens Health. 2020;38(2):220-225. doi:10.5534/wjmh.190028","Soares AH, et al. Effects of clomiphene citrate on male obesity-associated hypogonadism: a randomized, double-blind, placebo-controlled study. Int J Obes. 2018;42(5):953-963. doi:10.1038/s41366-018-0105-2","Saffati G, et al. Transl Androl Urol. 2024;13(9):1984-1990. doi:10.21037/tau-24-238","Choi J, Lee S, Lee CN. Isolated cortical vein thrombosis in an infertile male taking clomiphene citrate. Neurol Sci. 2021;42(4):1615-1616. doi:10.1007/s10072-020-04862-z","Shahid Z, et al. Clomiphene-induced myocardial infarction in a young male: a case report. Sci Prog. 2025;108(3). doi:10.1177/00368504251349392"]},interactions:[{with:"Aromatase inhibitors (anastrozole, letrozole)",kind:"pharmacodynamic",text:"They push the SAME lever — less estrogen feedback at the hypothalamus — so the testosterone effects do not add, and Forge models them as sharing one final path. The AI also blocks estrogen ACTION, which carries a measured fat and bone cost (Finkelstein 2013; Burnett-Bowie 2009), so the combination buys no extra testosterone and brings a cost of its own."},{with:"hCG",kind:"pharmacodynamic",text:"Randomized and measured: clomiphene +158 ng/dL, hCG +134, both together +153 (Habous 2018, 282 men, p=0.57 for the combination vs clomiphene alone). The combination was NOT better. Both end at the same Leydig cell, which is why Forge takes the larger of the two rather than adding them."},{with:"Exogenous testosterone (any route)",kind:"pharmacodynamic",text:"Pointless and contradictory. Exogenous testosterone suppresses LH and FSH; clomiphene works by raising them. Forge models every own-axis item at zero while exogenous testosterone is in the stack."},{with:"Anything that suppresses the axis (alcohol, opioids, a large deficit, short sleep)",kind:"additive",text:"These lower the baseline the drug then works from. Because the measured SERM effect is a roughly constant number of ng/dL (Hohl 2025) rather than a percentage, a lower baseline mostly means a lower END point, not a smaller rise."},{with:"Prescription medicines generally",kind:"pharmacokinetic",text:"No clinically important cytochrome-P450 interaction is established for clomiphene in men, unlike tamoxifen. That is an absence of documented interactions, not a guarantee — your prescriber has your full medication list and Forge does not."}],unknowns:["Whether it builds muscle in a man whose testosterone is already normal. The hormone rise there is measured (Tenover 1991, Bremner 1987); the body-composition consequence has never been measured in anyone who was not hypogonadal.","Whether an endogenous rise builds the same muscle as the same rise given from outside. The curve Forge runs the credit through (Bhasin 2001) came from exogenous testosterone with the gonadotropins switched off. This is the single biggest gap in this whole category.","The achieved testosterone level in the one trial that measured body composition (Soares 2018) is not published, so the 500 ng/dL bound Forge uses is inferred from the entry criterion plus the pooled rise — an assumption, not a measurement.","Dose-response. There is no within-trial dose ladder in men: 25 mg/day and 50 mg/day look indistinguishable across trials, and the 1,390 ng/dL figure came from 100 mg/day in five men.","Strength, function and performance. Nothing has measured them on clomiphene. The one trial in this class that did look (Liu 2002, hCG) found +2 kg of lean mass and NO improvement in shoulder or knee strength, gait, balance or physical activity — which is a warning that lean mass on a bioimpedance machine is not the same thing as being stronger.","Bone mineral density on treatment. Never measured in men on clomiphene.","Long-term safety from a randomized trial. Everything past 6 months is retrospective series."],bodyComp:"measured",bcMaxLevel:500,bcExtrapMaxLevel:1390,bcMaxBaseline:300,bcNote:"MEASURED up to ≈500 ng/dL, EXTRAPOLATED above it. Soares 2018 measured body composition by bioimpedance in obese men starting at 226 ± 70 ng/dL and found lean, fat-free and muscle mass all improved; the achieved level is not in the abstract, and 500 ng/dL is inferred from that baseline plus the pooled rise in obese men (+333 ng/dL, Tienforti 2023), so the bound itself is an ASSUMPTION. Above 500 the hormone rise IS measured (Tenover 1991 reached 1,390 ng/dL in healthy young men), but no trial has measured body composition there, so Forge runs it through the testosterone→lean curve, labels it an extrapolation, and starts its range at zero. The deeper gap: that curve (Bhasin 2001) was built on testosterone given from outside with the gonadotropins switched off. Whether an endogenous rise of the same size builds the same muscle has never been tested.",monitor:["Total testosterone (morning, 4–6 weeks in)","Estradiol (sensitive assay)","Hematocrit","PSA","LH/FSH","Vision changes: stop and call the prescriber"],fertility:"Preserved or improved — the main reason to pick it over testosterone.",timeCourse:"Levels move within 2 weeks; trials ran 8–30 weeks. Long-term data are retrospective.",wada:"WADA prohibited at all times, S4.2 (anti-estrogenic substances / SERMs).",suits:"Low testosterone (two morning draws under ~300) with a normal or slightly raised LH, especially when fertility matters. It also raises the number in men who are already normal — that part is measured — but what that buys you is not.",notSuits:'A clearly raised LH together with a low testosterone — "primary": the signal is already maximal and the testes are not acting on it, so raising the signal further is the wrong lever. (That is about how the testes RESPOND, not how they look or feel; see the LH note on the lab panel.) Anyone already on testosterone. And anyone who wants a muscle result rather than a lab result at a normal baseline, because that has never been measured on this drug.',levelRisks:[{min:1,text:"Estradiol rises on clomiphene, so breast tenderness or gynecomastia can appear; your prescriber tracks it along with hematocrit and PSA."}],gate:{secondaryOnly:!0}}},{id:"enclomiphene",name:"Enclomiphene citrate",category:"prescription",rx:!0,evidence:"moderate",status:`Not an FDA-approved drug and never has been: the Androxal new drug application drew a Complete Response Letter on 30 November 2015 and no approval followed. It reaches people through compounding pharmacies on a prescription. FDA's advisory committee voted 8–4 AGAINST putting it on the 503A bulks list on 8 June 2022, citing a lack of clinical efficacy evidence — but FDA has not acted on that vote, and enclomiphene citrate is still in 503A Category 1 ("bulk drug substances under evaluation", list updated 14 May 2026), where FDA says it does not intend to act against a compounder. It is NOT on the Category 2 "significant safety risks" list. WADA prohibited (S4.2).`,summary:"The purified trans-isomer of clomiphene, with the estrogenic cis-isomer removed. Two phase-3 trials reached testosterone levels equal to testosterone gel while raising LH and FSH and keeping sperm counts intact. Pooled rise in obesity-related low T: +216 ng/dL. The isomer story is real and the side-effect data lean its way — but no trial has ever randomized it against clomiphene, no trial has ever enrolled a man with a normal testosterone, and no trial has ever measured muscle on it.",mechanism:"Same target as clomiphene — estrogen-receptor blockade at the hypothalamus and pituitary, so LH and FSH rise and your own testes make more testosterone — but it is one of clomiphene's two isomers rather than the mixture. Clomiphene citrate is 62% (trans)enclomiphene and 38% (cis)zuclomiphene (Wiehle 2013). Enclomiphene is the antiestrogen that does the work; zuclomiphene is an estrogen AGONIST that contributes little to the testosterone rise and has a half-life of about 30 days against enclomiphene's ~10 h, so it accumulates. That accumulation is measured, not theoretical: in 15 men on clomiphene 25 mg/day for ≥6 weeks the median serum zuclomiphene was 44.0 ng/mL against 2.2 ng/mL of enclomiphene — a 20:1 ratio (Helo 2017). On chronic clomiphene almost all the circulating drug is the estrogenic isomer. Taking enclomiphene alone removes that.",effects:["Tienforti 2023 meta-analysis (obesity-related androgen deficiency, 7 studies, 292 men): enclomiphene +7.50 nmol/L ≈ +216 ng/dL (95% CI 6.52–8.48 nmol/L = 188–245 ng/dL), heterogeneity I²=4%. The SAME meta-analysis pooled clomiphene separately in the same population: +11.56 nmol/L ≈ +333 ng/dL (9.68–13.43). That is the only isomer-matched comparison in one population, and it puts enclomiphene at about 0.65 of clomiphene.","The two direct head-to-head comparisons do NOT reproduce that gap, and neither found a significant difference. Thomas 2023 (Cureus, 46 enclomiphene vs 32 clomiphene, ≥3 months, retrospective): mean rise +124.96 vs +177.30 ng/dL, p=0.491. Saffati 2024 (Transl Androl Urol, 66 men who took clomiphene and were then switched to enclomiphene): median +98 ng/dL on clomiphene, then a further +166 on enclomiphene, p=0.20 — enclomiphene numerically HIGHER. Hohl 2025 pooled both isomers together against testosterone gel and found no difference in total T (5.41 ng/dL, 95% CI −43 to +54).","Wiehle 2013 (phase 2, doi:10.1111/bju.12363) is the only dose-ranging trial, and it is a real dose-response rather than a flat line. Day-42 morning total T (C0) was 420 ± 212 on 6.25 mg (n=12), 404 ± 165 on 12.5 mg (n=7) and 604 ± 160 ng/dL on 25 mg (n=12), against 500 ± 278 on transdermal testosterone (across-group p=0.07). The 24-h means were 391 / 426 / 586 vs 546 (p=0.003) and the 24-h peaks (Cmax) 516 / 554 / 764 vs 908 (p=0.024). Measured as a RISE over each arm's own baseline, 6.25 and 12.5 mg are indistinguishable (≈43% of the 25 mg effect) and the step up comes at 25 mg; the responder analysis agrees (morning T >300 ng/dL in 58%, 71% and 100% of men).",`Wiehle's own conclusion was that the ceiling is the testis, not the drug: going from 12.5 to 25 mg roughly doubled LH (6.7 → 13.3 IU/L) but raised the 24-h mean testosterone only 27%, "suggesting a dose-limiting effect on the testosterone-producing Leydig cells of the testes, and the inability of enclomiphene citrate to stimulate the production of supernormal levels of testosterone".`,`It is far steadier than gel. Over 24 h at week 6, 0 of 272 samples in the 25 mg arm were below 300 ng/dL against 50 of 305 (16.4%) on gel, and the within-day range was 314 ± 65 ng/dL against 590 ± 465 (coefficient of variation 21% vs 79%). There is also a "legacy" effect: LH, FSH and testosterone were still raised 7 days after the last dose, which the drug's own ~10 h half-life cannot explain.`,"Kim 2016 (two parallel phase-3 RCTs, 256 overweight men with total T ≤300 and LH <9.4 IU/L, 16 weeks): testosterone rose on both doses; LH and FSH rose on enclomiphene and fell on gel, and sperm concentration was maintained on enclomiphene (+11.7% and +15.2% in the two studies) while gel suppressed it (−56.6% and −32.8%). Pooled across the whole SERM class, sperm concentration ran 70.4 million/mL higher than on gel (95% CI 41.6–99.2) and the risk of falling below 15 million/mL was 90% lower (RR 0.10, Hohl 2025).","DHT stays much lower than on gel: 20.4 ± 9.1 (12.5 mg) and 23.2 ± 20.2 (25 mg) against 51.6 ± 37.7 on gel, p<0.05 for both (Wiehle 2014).",`SERUM ESTRADIOL STILL RISES — this is the part of the "less estrogen" claim that does not hold. Thomas 2023 measured estradiol going 29.5 → 67 pg/mL on enclomiphene (p=0.003, n=18) against 31 → 37.6 on clomiphene (p=0.074, n=11), i.e. the opposite of the expected direction, and the testosterone:estradiol ratio fell from 13.2 to 8.7 on enclomiphene while it rose from 7.9 to 12.5 on clomiphene. Wiehle 2014 lists "mildly increased blood estradiol" as an enclomiphene adverse event. Mechanistically this has to happen: more testosterone means more substrate for aromatase, and removing zuclomiphene does nothing to aromatase. Saffati 2024's −5.92 pg/mL is a fall measured from an already clomiphene-raised level, not from an untreated baseline, so it does not contradict this.`,"What the isomer removal does change is estrogen ACTION and the side effects that track it. Saffati 2024 found adverse events in 31 of 66 men (47%) on clomiphene and 8 of 58 (13.8%) on enclomiphene in the same patients (p=0.001, OR 0.18, 95% CI 0.07–0.44) — see the tolerability block for the itemised rates.","Lipids point the same way. Clomiphene lowered HDL in the one trial that measured body composition (Soares 2018, p<0.001); enclomiphene did not move HDL, LDL, total cholesterol or triglycerides at any of three doses over 6 weeks (Wiehle 2013, across-group p=0.78 for HDL). In baboons given the isomers separately, zuclomiphene raised serum cholesterol 22% while enclomiphene lowered it 8%.","The one consistent enclomiphene-specific signal in the other direction: IGF-1 fell on every dose, from ≈96 to 50–62 µg/L over 6 weeks, significantly more than on gel (p≤0.008 for all three doses). Levels stayed inside the reference range and nobody knows what it means.","NO enclomiphene trial has ever enrolled a man with a normal testosterone. Wiehle 2013 enrolled 48 and had to exclude 4 whose baseline came back above 350. Every published entry criterion is total T ≤300–350 with LH <9.4–12. So Forge's eugonadal numbers are an inference — see the assumption note on the curve below.","Body composition and strength: not measured in any enclomiphene trial, at any baseline, ever. Forge credits muscle only up to 604 ng/dL and treats all of it as an unproven extrapolation, with a range starting at zero."],risks:["Not FDA-approved, so there is no approved label, no approved dose and no post-marketing safety surveillance; compounded product quality varies by pharmacy.","No long-term (multi-year) safety data at all. The longest randomized exposure is 16 weeks; clomiphene by contrast has a 400-man series out to 7 years and a 12,318-man claims cohort.",'Serum estradiol goes UP, not down (Thomas 2023: 29.5 → 67 pg/mL). The "no estrogen" framing is wrong; what the evidence supports is fewer estrogen-mediated SIDE EFFECTS, not a lower estradiol.',"IGF-1 fell on every dose in phase 2, more than on testosterone gel. The significance of that is unknown, and for someone whose goal is muscle it is the one finding that should give pause.","In phase 3 the two treatment discontinuations in the 25 mg arm were for a high hematocrit/hemoglobin and a high PSA — the same two things any testosterone-raising therapy is monitored for.","It still needs testes that respond to the signal and a pituitary that is not the problem: a clearly raised LH with a low testosterone means the signal is already maximal and is not being acted on, and this drug works by raising the signal. Nothing about testis size or feel tells you which case you are in — only LH does."],typicalUse:"Prescribed off-label from a compounding pharmacy for secondary hypogonadism, especially when fertility matters; the prescriber sets dosing and monitors labs.",sources:["Kim ED, McCullough A, Kaminetsky J. Oral enclomiphene citrate raises testosterone and preserves sperm counts in obese hypogonadal men, unlike topical testosterone: restoration instead of replacement. BJU Int. 2016;117(4):677-685. doi:10.1111/bju.13337","Wiehle RD, et al. Enclomiphene citrate stimulates testosterone production while preventing oligospermia: a randomized phase II clinical trial comparing topical testosterone. Fertil Steril. 2014;102(3):720-727. doi:10.1016/j.fertnstert.2014.06.004","Wiehle RD, et al. Testosterone restoration using enclomiphene citrate in men with secondary hypogonadism: a pharmacodynamic and pharmacokinetic study. BJU Int. 2013;112(8):1188-1200. doi:10.1111/bju.12363","Kaminetsky J, et al. Oral enclomiphene citrate stimulates the endogenous production of testosterone and sperm counts in men with low testosterone: comparison with testosterone gel. J Sex Med. 2013;10(6):1628-1635. doi:10.1111/jsm.12116","Helo S, Mahon J, Ellen J, Wiehle R, Fontenot G, Hsu K, Feustel P, Welliver C, McCullough A. Serum levels of enclomiphene and zuclomiphene in men with hypogonadism on long-term clomiphene citrate treatment. BJU Int. 2017;119(1):171-176. doi:10.1111/bju.13625","Saffati G, Kassab J, Orozco Rendon D, Hinojosa-Gonzalez DE, Kronstedt S, Lipshultz LI, Khera M. Safety and efficacy of enclomiphene and clomiphene for hypogonadal men. Transl Androl Urol. 2024;13(9):1984-1990. doi:10.21037/tau-24-238","Thomas J, Suarez Arbelaez MC, Narasimman M, et al. Efficacy of clomiphene citrate versus enclomiphene citrate for male infertility treatment: a retrospective study. Cureus. 2023;15(7):e41476. doi:10.7759/cureus.41476","Rodriguez KM, Pastuszak AW, Lipshultz LI. Enclomiphene citrate for the treatment of secondary male hypogonadism. Expert Opin Pharmacother. 2016;17(11):1561-1567. doi:10.1080/14656566.2016.1204294","Tienforti D, et al. Selective modulation of estrogen receptor in obese men with androgen deficiency: a systematic review and meta-analysis. Andrology. 2023;11(6):1067-1076. doi:10.1111/andr.13373","Hohl A, et al. Clomiphene or enclomiphene citrate for the treatment of male hypogonadism: a systematic review and meta-analysis of randomized controlled trials. Arch Endocrinol Metab. 2025;69(5):e250093. doi:10.20945/2359-4292-2025-0093","U.S. FDA. Bulk drug substances nominated for use in compounding under section 503A of the FD&C Act — Category 1, updated 14 May 2026.","U.S. FDA. Pharmacy Compounding Advisory Committee, summary minutes, 8 June 2022 (enclomiphene citrate: 4 yes / 8 no / 0 abstain against inclusion on the 503A Bulks List).",e],model:{kind:"tEndogenous",dose:{unit:"% of the studied regimen",default:100,label:"as studied (the dose carried through phase 3)",studied:[25,100],note:"The only dose-ranging trial tested three arms. The two lower ones produced about 43% of the top arm's rise and were not different from each other; the step up came at the top dose. Your prescriber sets the dose."},response:[[0,0],[25,.43],[50,.43],[100,1]],tPctByBaseline:[[150,144],[200,108],[250,86],[300,72],[350,62],[400,54],[450,48],[500,43],[550,39],[650,32],[800,24],[1e3,17]],rampWeeks:6,maxLevel:764,axis:"serm",ceilingNg:764,tCI:[.8,1.45],e2Pct:85,e2ActionPct:85,shbgDelta:3,e2Note:"Estradiol goes UP on enclomiphene, not down — about as much as on clomiphene, because what drives it is the extra testosterone being aromatised and removing the cis-isomer does nothing to aromatase. Thomas 2023 measured 29.5 → 67 pg/mL (p=0.003). What the isomer removal changes is estrogen ACTION in tissue, and the side effects that follow from it, not the number on the lab report. As with clomiphene, Forge credits no fat change from a SERM's serum-E2 rise.",e2ActionNote:"Forge tracks estrogen ACTION separately from serum estradiol, and applies a fat effect only when action is BLOCKED (aromatase inhibitors, Finkelstein 2013). A SERM raises the hormone while blocking the receptor centrally and acting as an agonist or antagonist elsewhere depending on tissue — net direction unknown — so no fat term is applied here for either isomer. The e2ActionPct figure is carried for documentation and is not read by the fat model for SERMs.",shbgNote:"SHBG rises a little, as on clomiphene; the pooled SERM change was not significant (+3.63 nmol/L, p=0.09, Hohl 2025). Forge models +3 nmol/L, and the bioavailable fraction is treated as unchanged (measured directly for clomiphene in Bremner 1987: 65% → 66% of total).",interactions:[{with:"Clomiphene",kind:"pharmacodynamic",text:"The same molecule minus the cis-isomer, so taking both is taking one drug twice. No trial has randomized one against the other."},{with:"Aromatase inhibitors",kind:"pharmacodynamic",text:"Same shared lever as clomiphene, and the same conclusion: no extra testosterone, plus the AI’s own estrogen-action cost."},{with:"hCG",kind:"pharmacodynamic",text:"One final common path (the Leydig cell), so not additive. The direct evidence is on the clomiphene + hCG pair (Habous 2018); it has never been tested with enclomiphene."},{with:"Exogenous testosterone",kind:"pharmacodynamic",text:"Opposite directions: testosterone suppresses LH and FSH, this raises them. Modeled at zero while exogenous testosterone is in the stack."},{with:"Compounding variability",kind:"pharmacokinetic",text:"Not a drug interaction, but it belongs here: enclomiphene is not an FDA-approved product and reaches people through compounding pharmacies, so the content of what is dispensed is not verified the way an approved product’s is."}],unknowns:["Body composition. No enclomiphene trial has ever measured it, at any baseline. Every lean figure Forge shows for it is an extrapolation.","Eugonadal men. No trial has enrolled one, so the hormone rise above about 350 ng/dL is itself inferred rather than measured — a weaker position than clomiphene, which has been measured in healthy men.","Whether it really is better tolerated. The isomer rationale is sound and the one direct comparison favours it (13.8% vs 47%, Saffati 2024), but that study is retrospective, unblinded and within-patient, and no trial has randomized the two.","Safety past 16 weeks. The phase-3 programme ran 16 weeks. There is no long-term safety dataset of any kind, which is the single most important thing to know about it and the main respect in which clomiphene is better characterised.","Regulatory standing. FDA’s advisory committee voted 8–4 against the 503A bulks list in 2022 citing a lack of clinical efficacy evidence; FDA has not acted on that vote either way.","Strength and function, bone density, fertility outcomes beyond sperm concentration: none measured."],bodyComp:"extrapolated",bcMaxLevel:604,bcNote:'EXTRAPOLATED TWICE OVER, and still the weakest row of the three SERMs. (1) No enclomiphene trial has ever measured body composition, at any baseline, so the 604 ng/dL bound is not "where a body-composition trial landed" — it is simply the highest morning group mean any enclomiphene trial reached (Wiehle 2013, 25 mg, day-42 C0 = 604 ± 160), and Forge refuses to run the muscle curve above a level the drug has never been shown to produce. (2) No enclomiphene trial has ever enrolled a eugonadal man, so the hormone rise shown above ~350 ng/dL is itself inferred. And the Bhasin curve the credit runs through came from testosterone given from OUTSIDE with the gonadotropins switched off, which is not what this drug does. Range starts at zero.',tolerability:{grade:"good",comparedWith:"placebo in its own randomized trials; clomiphene in one retrospective within-patient comparison",evidence:"rct",headline:"Fewer side effects than clomiphene in the only direct comparison: 13.8% vs 47% of the same men (p=0.001, OR 0.18).",discontinuation:{pct:2.4,n:2,of:85,note:"Both in the 25 mg arm of the phase-3 programme, and both for a lab value rather than a symptom: one raised hematocrit/hemoglobin, one raised PSA. The testosterone-gel arm had one discontinuation for the same hematocrit reason.",source:"Kim 2016 (Hohl 2025 safety table)"},events:[{label:"Any adverse event attributed to study drug",pct:21,n:53,of:256,arm:"all arms pooled",p:"no significant difference between enclomiphene, testosterone gel and placebo",source:"Kim 2016, two phase-3 RCTs"},{label:"Any adverse event (vs clomiphene, same patients)",pct:13.8,n:8,of:58,arm:"enclomiphene",vs:{pct:47,n:31,of:66,label:"clomiphene"},p:"0.001 (OR 0.18, 95% CI 0.07–0.44)",source:"Saffati 2024"},{label:"Decreased libido",pct:8.6,n:5,of:58,arm:"enclomiphene",vs:{pct:33.3,n:22,of:66,label:"clomiphene"},p:"0.001 (OR 0.18, 95% CI 0.06–0.53)",source:"Saffati 2024"},{label:"Mood changes",pct:0,n:0,of:58,arm:"enclomiphene",vs:{pct:9.1,n:6,of:66,label:"clomiphene"},p:"0.03",source:"Saffati 2024"},{label:"Reduced energy",pct:5.2,n:3,of:58,arm:"enclomiphene",vs:{pct:16.7,n:11,of:66,label:"clomiphene"},p:"0.044",source:"Saffati 2024"},{label:"Erectile dysfunction",pct:8.6,n:5,of:58,arm:"enclomiphene",vs:{pct:18.2,n:12,of:66,label:"clomiphene"},p:"0.12 — not significant",source:"Saffati 2024"},{label:"Gynecomastia",pct:0,n:0,of:58,arm:"enclomiphene",vs:{pct:3,n:2,of:66,label:"clomiphene"},p:"0.49 — not significant, and the numbers are far too small to separate",source:"Saffati 2024"},{label:"Hematocrit change",pct:null,n:null,of:66,arm:"median 0%",vs:{pct:null,n:null,of:66,label:"clomiphene, median +0.4%"},p:"0.85 — no difference",source:"Saffati 2024"},{label:"Treatment-emergent adverse events",pct:null,n:null,of:124,arm:"9–20% across all arms, same on enclomiphene as on placebo; the only enclomiphene events were one mildly raised estradiol and two headaches",p:"no discontinuations for adverse events, no serious adverse events on enclomiphene",source:"Wiehle 2014, phase 2b"},{label:"HDL cholesterol",pct:null,n:null,of:48,arm:"unchanged at 6.25, 12.5 and 25 mg over 6 weeks (across-group p=0.78); LDL, total cholesterol and triglycerides also unchanged",p:"contrast: clomiphene lowered HDL, p<0.001 (Soares 2018)",source:"Wiehle 2013"},{label:"IGF-1",pct:null,n:null,of:48,arm:"FELL on every dose, ≈96 → 50–62 µg/L over 6 weeks, significantly more than on testosterone gel (p≤0.008)",p:"the one tolerability signal that runs against enclomiphene; stayed within the reference range and the meaning is unknown",source:"Wiehle 2013"}],note:`Read this carefully before treating it as settled. The randomized evidence says enclomiphene is no worse than placebo (Kim 2016, Wiehle 2014) — but there has never been a randomized trial of enclomiphene against clomiphene, so the randomized evidence cannot rank them. The entire direct comparison is Saffati 2024: 66 men at one centre, retrospective, unblinded, adverse events counted from clinic notes, everyone took clomiphene FIRST and enclomiphene second with no washout, and the authors list the problems themselves — carry-over from zuclomiphene's ~30-day half-life, different reasons for switching, and a hypogonadal baseline for clomiphene against an already-corrected one for enclomiphene. A second-drug-in-sequence is also simply less likely to have its side effects written down. The mechanism is real and the direction is consistent (lower estradiol relative to clomiphene, no HDL fall, zuclomiphene the estrogen agonist removed), which is why the grade is "good" and not "unknown" — but one unblinded chart review is why it is capped there and not called proven.`,sources:["Saffati G, et al. Safety and efficacy of enclomiphene and clomiphene for hypogonadal men. Transl Androl Urol. 2024;13(9):1984-1990. doi:10.21037/tau-24-238","Kim ED, McCullough A, Kaminetsky J. BJU Int. 2016;117(4):677-685. doi:10.1111/bju.13337 (safety table as tabulated by Hohl 2025, doi:10.20945/2359-4292-2025-0093)","Wiehle RD, et al. Fertil Steril. 2014;102(3):720-727. doi:10.1016/j.fertnstert.2014.06.004","Wiehle RD, et al. BJU Int. 2013;112(8):1188-1200. doi:10.1111/bju.12363"]},monitor:["Total testosterone (morning — Wiehle 2013 showed a single morning draw predicts the 24-h mean, r=0.93)","Estradiol (sensitive assay — it rises)","Hematocrit","PSA","LH/FSH","IGF-1 (it fell on every dose in phase 2)"],fertility:"Preserved, and this is the one place enclomiphene has a clear, randomized, measured advantage over testosterone: LH and FSH rise, and sperm concentration was maintained (+11.7% and +15.2%) where gel suppressed it (−56.6% and −32.8%) in the same trials (Kim 2016).",timeCourse:"Testosterone rises within 14 days and plateaus by about 4 weeks; LH, FSH and testosterone were still raised 7 days after the last dose.",wada:"WADA prohibited at all times, S4.2 (anti-estrogenic substances / SERMs). Clomifene is named on the list and enclomiphene is its trans-isomer, so the class covers it; the DoD prohibited-ingredient list names enclomiphene directly.",suits:"Overweight men with secondary hypogonadism (T ≤300, with a normal or only slightly raised LH) who want fertility preserved, and men who tried clomiphene and could not tolerate it — that second group is where the evidence for it is strongest.",notSuits:"Anyone in the normal range: not because it would do nothing, but because no enclomiphene trial has ever studied one, so Forge is inferring the shape of the response from clomiphene. Clomiphene is the better-evidenced choice at a normal baseline and costs a fraction as much. Also: no FDA approval, no long-term safety data, and an unexplained fall in IGF-1.",gate:{secondaryOnly:!0}}},{id:"hcg",name:"hCG (human chorionic gonadotropin) — an injection, but not testosterone",category:"prescription",rx:!0,evidence:"moderate",status:"Prescription only, and an injection — but NOT testosterone: it makes your own testes produce testosterone instead of replacing it. Regulated as a biologic since 2020, which took it out of ordinary compounding. WADA prohibited in males (S2 gonadotropins).",summary:"Acts like LH directly on the testes, so it works even when the pituitary signal is the problem. The one placebo-controlled trial in older men with low testosterone raised T about 150% and added roughly 2 kg of lean mass in 3 months — but strength, balance and physical function did not improve at all.",mechanism:"hCG binds the LH receptor on Leydig cells, driving testosterone production inside the testis. That intratesticular testosterone is also what sperm production needs, which is why it is used alongside testosterone therapy to protect fertility.",effects:["Liu 2002 (double-blind RCT, 40 men over 60 with low T, 3 months): total and free T and estradiol up about 150%; lean body mass +2 kg (p<0.001), fat mass −1 kg; LH and FSH fell and testis volume dropped about 5 mL.","Crucially, in that same trial shoulder and knee strength, physical activity, gait and balance did not improve. More lean mass on the scan did not become more function.","Habous 2018 (randomized, 282 hypogonadal men wanting fertility, baseline ≈67 ng/dL, 5,000 IU twice weekly, 12 weeks): clomiphene +158, hCG +134, both together +153 ng/dL — the combination was no better than clomiphene alone (p=0.57). This is the single best piece of evidence that these drugs do not add up.","Alongside testosterone therapy it preserves sperm: in Hsieh 2013 no man became azoospermic and semen parameters held steady.","It works at a normal baseline too, which is the point of the hCG stimulation test: Cailleux-Bounacer 2008 found dose-dependent testosterone and estradiol rises in NORMAL men (peak at 72 h), and Panidis 2002 gave 5,000 IU to 30 fertile eugonadal men aged 23–38 and tracked the testosterone rise for a week. Those are single injections, though — nobody has run chronic hCG in a eugonadal man, so Forge's numbers above ~430 ng/dL are a conservative assumption, not a measurement.","Forge credits muscle up to about 870 ng/dL here, inferred from Liu 2002's ≤15 nmol/L (433 ng/dL) entry criterion and its reported +150% rise. The exact achieved level is not in the paper, so that bound is an assumption."],risks:["Nipple tenderness and gynecomastia (estradiol rises with it).","Suppresses your own LH and FSH while you are on it, and testis volume fell in the trial.","Injections, with the usual infection and site-reaction risks.","Not available through ordinary compounding since it became a licensed biologic; brand-name products need a prescription."],typicalUse:"Prescribed and monitored by a physician for secondary hypogonadism or to protect fertility alongside testosterone therapy; the prescriber sets dose and frequency.",sources:["Liu PY, Wishart SM, Handelsman DJ. A double-blind, placebo-controlled, randomized clinical trial of recombinant human chorionic gonadotropin on muscle strength and physical function and activity in older men with partial age-related androgen deficiency. J Clin Endocrinol Metab. 2002;87(7):3125-3135.","Habous M, et al. Clomiphene citrate and human chorionic gonadotropin are both effective in restoring testosterone in hypogonadism: a short-course randomized study. BJU Int. 2018;122(5):889-897.","Hsieh TC, et al. Concomitant intramuscular human chorionic gonadotropin preserves spermatogenesis in men undergoing testosterone replacement therapy. J Urol. 2013;189(2):647-650.","Rastrelli G, et al. Factors affecting spermatogenesis upon gonadotropin-replacement therapy: a meta-analytic study. Andrology. 2014;2(6):794-808.",e],model:{kind:"tEndogenous",dose:{unit:"% of the studied regimen",default:100,label:"as studied (prescriber-set dose)",studied:[0,100]},response:[[0,0],[100,1]],tPctByBaseline:[[150,200],[250,160],[350,150],[430,140],[500,120],[600,95],[800,65],[1100,40]],rampWeeks:4,maxLevel:1100,axis:"gonadotropin",ceilingNg:1100,tCI:[.6,1.4],e2Pct:150,e2ActionPct:150,shbgDelta:0,e2Note:"Estradiol rose about 150% alongside testosterone in Liu 2002 — hCG drives the whole steroidogenic pathway, not just testosterone. Fat fell 1 kg in that trial, which is the measured number Forge uses; no separate estradiol term is applied.",tolerability:{grade:"moderate",comparedWith:"placebo in one 40-man randomized trial; no head-to-head against a SERM on adverse events",evidence:"rct",headline:"No adverse-event table has ever been published for hCG in this population. What is documented is that it shrinks the testes and roughly doubles estradiol.",discontinuation:null,events:[{label:"Testis volume",pct:null,n:null,of:20,arm:"fell about 5 mL on hCG over 3 months",p:"a measured, expected pharmacological effect, and the reason it is not a long-term monotherapy",source:"Liu 2002"},{label:"Estradiol",pct:null,n:null,of:20,arm:"rose about 150%, in step with testosterone",p:"hCG drives the whole steroidogenic pathway; nipple tenderness and gynecomastia are the usual complaints",source:"Liu 2002"},{label:"LH and FSH",pct:null,n:null,of:20,arm:"suppressed while on treatment",p:"the opposite of what a SERM does, and worth knowing if the point of avoiding testosterone was to keep the axis running",source:"Liu 2002"},{label:"Injection-site reactions and infection",pct:null,n:null,of:null,arm:"the usual injection risks; not quantified in these trials",source:"no quantified data"}],note:'Liu 2002 is 40 men for 3 months, and it reported efficacy endpoints rather than a safety table; Habous 2018 reported neither. So the honest reading is "no quantified tolerability data", and the "moderate" grade is carried by the two things that ARE measured — testicular shrinkage and a 150% estradiol rise — plus the fact that it is an injection rather than a tablet.',sources:["Liu PY, Wishart SM, Handelsman DJ. J Clin Endocrinol Metab. 2002;87(7):3125-3135.","Habous M, et al. BJU Int. 2018;122(5):889-897."]},interactions:[{with:"Clomiphene / enclomiphene",kind:"pharmacodynamic",text:"Not additive, and this is the one combination in the category that has actually been randomized: clomiphene +158, hCG +134, both +153 ng/dL (Habous 2018, p=0.57). Forge takes the larger, not the sum."},{with:"Exogenous testosterone",kind:"pharmacodynamic",text:"The one pairing here that is deliberate and supported: low-dose hCG alongside testosterone therapy maintains intratesticular testosterone and sperm production, which testosterone alone suppresses. That is a fertility-preservation strategy run by a clinician, not a muscle strategy."},{with:"Aromatase inhibitors",kind:"pharmacodynamic",text:"Commonly stacked to blunt the estradiol rise, which on hCG is large (about +150%, Liu 2002). The AI adds no testosterone on top and brings its own fat and bone cost, so what it buys is symptom control, not more hormone."}],unknowns:["Chronic use in a man with a normal testosterone. Nobody has done it. The eugonadal numbers come from single-injection Leydig stimulation TESTS (Cailleux-Bounacer 2008, Panidis 2002), which is a different thing from taking it for a year.","The achieved level in the trial that weighed people. Liu 2002 does not publish it, so the 870 ng/dL bound is inferred from the ≤433 entry criterion plus the reported +150%.","Why the lean mass did not translate. Liu 2002 is the only placebo-controlled lean-mass result in this category and it found +2 kg of lean with NO gain in shoulder or knee strength, gait, balance or physical activity. Whether that reflects the measurement, the population (men over 60) or the lean mass being something other than contractile muscle is unresolved, and it is the most important unknown here.",'Adverse events. No trial has ever tabulated them against a comparator in this population. The "moderate" grade rests on two measured pharmacological effects (testes shrank about 5 mL; estradiol rose about 150%) rather than on a safety table.',"Dose-response in men for body composition, and anything beyond 3 months."],bodyComp:"measured",bcMaxLevel:870,bcMaxBaseline:433,bcNote:"MEASURED, and the only placebo-controlled lean-mass result in this whole class: Liu 2002, 40 men over 60, 3 months, lean +2 kg (p<0.001) and fat −1 kg (p<0.05) — with NO improvement in shoulder or knee strength, gait, balance or physical activity. The 870 ng/dL bound is inferred from the ≤433 ng/dL entry criterion and the reported +150%; the achieved mean is not published, so the bound is an assumption.",monitor:["Total testosterone and estradiol","Hematocrit","Testis volume (it fell ~5 mL in the trial)","LH/FSH (they are suppressed while you use it)"],fertility:"The reason it exists: intratesticular testosterone is what sperm production needs, so it is used alongside testosterone therapy to protect fertility.",timeCourse:"Levels rise within days; Liu 2002 ran 3 months.",wada:"WADA prohibited at all times in males, S2.2 (chorionic gonadotropin).",suits:"Low testosterone with fertility to protect, including men already on testosterone therapy. It works even when the pituitary signal is the problem, because it replaces LH.",notSuits:'"Primary" failure, where the Leydig cells cannot respond to the signal however loudly it is sent — hCG replaces the LH signal, so a testis that is already ignoring a maximal LH will ignore this too. That is a response problem, not a size problem, and LH is the only way to see it. Also anyone who would rather not inject. At a normal baseline it still raises the number — that is what a Leydig stimulation test is — but no one has run it chronically in a eugonadal man or measured what it does to him.',gate:{secondaryOnly:!0},levelRisks:[{min:1,text:"Estradiol rises with hCG: breast tenderness and gynecomastia are the common complaints, and your own LH and FSH are suppressed while you use it."}]}},{id:"aromatase_inhibitor",name:"Aromatase inhibitor (anastrozole, letrozole), off-label",category:"prescription",rx:!0,evidence:"strong",status:"Prescription only; approved for breast cancer, used off-label in men. WADA prohibited (S4.1).",summary:"These reliably raise testosterone by 30–150% by blocking its conversion to estradiol. They are also the clearest case in this whole area where a big testosterone number bought nothing: two year-long randomized trials measured body composition and strength and found no change, and spine bone density fell. Forge raises your testosterone number and deliberately credits zero muscle.",mechanism:"Blocks aromatase, so less testosterone becomes estradiol. Lower estradiol means less negative feedback, so LH rises and testosterone rises. The catch is that men need estradiol — it is what protects bone and, per Finkelstein 2013, what keeps fat mass down.",effects:["Leder 2004 (RCT, men 62–74 with T under 350): daily dosing took total T from 343 ± 61 to 572 ± 139 ng/dL (+67%); a twice-weekly schedule gave +31%. No change in quality of life, erectile function or hematocrit.","Burnett-Bowie 2009 (RCT, men ≥60, 12 months, anastrozole 1 mg): total T 11.2 → 18.2 nmol/L (323 → 525 ng/dL) at 3 months, bioavailable T 2.7 → 5.4 nmol/L — and body composition (CT and DXA) and strength did not change. Estradiol fell only 55.8 → 42.2 pmol/L (−24%), because the rising testosterone feeds the enzyme more substrate.",'A second 12-month RCT (Burnett-Bowie 2009b, n=69) found spine bone density fell on anastrozole (1.121 → 1.102 g/cm²) while it rose on placebo (1.180 → 1.189), p=0.0014. Estradiol 15 → 12 pg/mL. "Aromatase inhibition does not improve skeletal health in aging men."','Loves 2013 (RCT, letrozole, 42 men with BMI >35, 6 months): estradiol 119 → 59 pmol/L, LH 3.3 → 8.8 IU/L, total T 8.6 → 21.5 nmol/L (248 → 620 ng/dL, +150%) — and "significant effects on the predefined endpoints were not observed", body composition included.',"Finkelstein 2013 (NEJM, 400 men, goserelin + graded testosterone ± anastrozole): the cohort × dose interaction was significant for % body fat (P=0.001), intra-abdominal fat (P=0.021) and subcutaneous fat (P=0.029), and NOT significant for lean mass (P=0.22), thigh-muscle area (P=0.20) or leg-press strength (P=0.91). Androgen runs muscle; estrogen runs fat.","The catch that reconciles all of it: Finkelstein crushed estradiol to 1–3 pg/mL (the testes were switched off, so anastrozole had almost no substrate to work on). In a man with a working axis the same 1 mg only drops estradiol 20–50%, which is why the real-world AI trials found no fat effect. Forge scales the fat penalty by how much estrogen action you actually lose, so a real-world AI gives a small number with a range that includes zero.","Two more failures to replicate the fat penalty: Mauras 2000 (anastrozole 1 mg, 10 weeks, young men; estradiol −48%, no change in fat-free mass, fat mass, protein synthesis or strength) and Dias 2016/2017 (RCT, 12 months, older men; the AI arm LOST abdominal subcutaneous fat and leptin)."],risks:["Spine bone-mineral density fell over a year in a randomized trial. In a man already at risk (endurance athlete, low energy availability) that is a real concern.","Low estradiol in men causes joint aches, low libido and, over time, bone loss.","One pulmonary embolism occurred in the anastrozole arm of a head-to-head trial (in a man with a prior clot).","Because it lowers estradiol, it works against fat loss, which is usually the opposite of the goal."],typicalUse:"Off-label, physician-prescribed and monitored, usually for men with low testosterone and a high estradiol ratio or for gynecomastia; dose and schedule are the prescriber's call, with estradiol and bone density watched.",sources:["Leder BZ, et al. Effects of aromatase inhibition in elderly men with low or borderline-low serum testosterone levels. J Clin Endocrinol Metab. 2004;89(3):1174-1180.","Burnett-Bowie SM, et al. Effects of aromatase inhibition in hypogonadal older men: a randomized, double-blind, placebo-controlled trial. Clin Endocrinol. 2009;70(1):116-123.","Burnett-Bowie SM, et al. Effects of aromatase inhibition on bone mineral density and bone turnover in older men with low testosterone levels. J Clin Endocrinol Metab. 2009;94(12):4785-4792.","Loves S, et al. Letrozole once a week normalizes serum testosterone in obesity-related male hypogonadism. Eur J Endocrinol. 2008;158(5):741-747.","Loves S, et al. Effects of letrozole on the lipid profile, body composition and quality of life in obese men with hypogonadotropic hypogonadism: a randomized placebo-controlled trial. Eur J Endocrinol. 2013;169(5):705-714.","Finkelstein JS, et al. Gonadal steroids and body composition, strength, and sexual function in men. N Engl J Med. 2013;369(11):1011-1022. doi:10.1056/NEJMoa1206168","Mauras N, et al. Estrogen suppression in males: metabolic effects. J Clin Endocrinol Metab. 2000;85(7):2370-2377. doi:10.1210/jcem.85.7.6676","Dias JP, et al. Testosterone vs. aromatase inhibitor in older men with low testosterone: effects on cardiometabolic parameters. Andrology. 2017;5(1):31-40. doi:10.1111/andr.12284","Colleluori G, et al. Aromatase inhibitors plus weight loss improves the hormonal profile of obese hypogonadal men without causing major side effects. Front Endocrinol. 2020;11:277. doi:10.3389/fendo.2020.00277",e],model:{kind:"tEndogenous",dose:{unit:"% of the studied regimen",default:100,label:"as studied (prescriber-set dose)",studied:[0,100]},response:[[0,0],[100,1]],tPctByBaseline:[[200,70],[320,67],[450,60],[600,58],[900,40]],rampWeeks:4,maxLevel:800,tLeanShare:0,axis:"ai",ceilingNg:800,tCI:[.45,2.2],e2Pct:-35,e2ActionPct:-35,shbgDelta:0,shbgNote:"SHBG did not change on anastrozole (Mauras 2000).",e2Note:"This is the only item where Forge applies the Finkelstein 2013 fat term, because it is the only one that blocks estrogen SYNTHESIS. The penalty is scaled by how much estrogen action is lost: a real-world 20–50% drop is a fraction of Finkelstein's ~90%.",tolerability:{grade:"poor",comparedWith:"placebo over 12 months (Burnett-Bowie 2009); clomiphene over 12 weeks (Helo 2015)",evidence:"rct",headline:"Spine bone density FELL over a year of randomized treatment. That is a measured harm, not a symptom, and it is why this is the one item here graded poor.",discontinuation:{pct:7.7,n:1,of:13,note:"One man stopped for a rash in the 12-week randomized comparison with clomiphene; the clomiphene arm lost one man to follow-up rather than to an adverse event.",source:"Helo 2015 (Hohl 2025 safety table)"},events:[{label:"Spine bone mineral density",pct:null,n:null,of:69,arm:"FELL over 12 months of randomized anastrozole vs placebo",p:"the reason Forge grades this poor; relevant to anyone with a history of endurance training or low energy availability",source:"Burnett-Bowie 2009"},{label:"Pulmonary embolism",pct:7.7,n:1,of:13,arm:"anastrozole",vs:{pct:0,n:0,of:13,label:"clomiphene"},p:"in a man with a prior DVT; n=13 per arm, so this is a single event and not a rate",source:"Helo 2015"},{label:"Joint aches and low libido",pct:null,n:null,of:null,arm:"the standard aromatase-inhibitor complaints; not separately quantified in the male off-label trials",p:"mechanistically expected — low estradiol is the mechanism and the problem",source:"Burnett-Bowie 2009"},{label:"Symptom score vs clomiphene",pct:null,n:null,of:13,arm:"ADAM score 38.0 ± 1.3 on anastrozole vs 40.0 ± 1.3 on clomiphene",p:"0.634 — no difference in how men felt",source:"Helo 2015"}],note:'Unusually for this catalogue, the tolerability problem here is not what men report — symptom scores matched clomiphene — it is what the scan showed. Bone is the endpoint that decides this grade, and it took a 12-month randomized trial to see it. Forge already credits zero muscle for this item; "poor tolerability" is the second half of the same story.',sources:["Burnett-Bowie SM, et al. Effects of aromatase inhibition on bone mineral density and bone turnover in older men with low testosterone levels. J Clin Endocrinol Metab. 2009;94(12):4785-4792.","Helo S, et al. A randomized prospective double-blind comparison trial of clomiphene citrate and anastrozole in raising testosterone in hypogonadal infertile men. J Sex Med. 2015;12(8):1761-1769. (safety data as tabulated by Hohl 2025, doi:10.20945/2359-4292-2025-0093)"]},interactions:[{with:"SERMs (clomiphene, enclomiphene, tamoxifen)",kind:"pharmacodynamic",text:"Same lever, so no extra testosterone — and the costs do not cancel. A SERM raises estradiol while blocking the receptor centrally; an AI removes the hormone itself everywhere, including bone and fat tissue."},{with:"hCG",kind:"pharmacodynamic",text:"Used to blunt hCG’s large estradiol rise. It adds no testosterone and brings its own measured bone and fat cost."},{with:"Anything that depends on estrogen action",kind:"pharmacodynamic",text:"That includes bone maintenance and fat regulation in men. This is the mechanism, not a side effect: Finkelstein 2013 showed androgen runs muscle and estrogen runs fat, and the one-year randomized trial measured spine bone density FALLING on anastrozole (Burnett-Bowie 2009)."}],unknowns:["Nothing important about muscle is unknown here, which is why this item is graded as having no muscle effect rather than an unmeasured one: two separate 12-month randomized trials measured body composition and strength and found no change, while bone density fell.","The one population where the fat cost did not appear is severely obese hypogonadal men (Colleluori 2020). Whether that generalises past severe obesity is unknown.","Long-term fracture risk in men treated this way off-label has never been studied."],bodyComp:"none",bcMaxLevel:0,bcNote:"MEASURED AND NULL. Two 12-month randomized trials (Burnett-Bowie 2009 ×2) measured body composition by CT and DXA and strength and found no change; Loves 2013 found nothing on any predefined endpoint despite +150% testosterone; Mauras 2000 found no change in fat-free mass, fat mass or protein synthesis. Forge therefore raises your testosterone number and credits ZERO muscle — the clearest case in this whole area that a bigger number is not more muscle.",monitor:["Estradiol (sensitive assay) — the point is not to crush it","Total testosterone","Spine bone-mineral density if used beyond a few months","Lipids"],fertility:"LH and FSH rise, so spermatogenesis is preserved or improved; it is used off-label in male infertility.",timeCourse:"Testosterone peaks at ~3 months and drifts back down by 12 (Burnett-Bowie 2009).",wada:"WADA prohibited at all times, S4.1 (aromatase inhibitors).",suits:"Obese men with low testosterone and a genuinely high estradiol, under a prescriber — and even then for the hormone profile, not for muscle.",notSuits:"Anyone whose goal is muscle (measured: none), anyone at risk of bone loss (endurance athletes, low energy availability), and anyone with a normal estradiol.",leanNullNote:"two 12-month randomized trials measured body composition and strength on it and found no change, and spine bone density fell",gate:{secondaryOnly:!0},levelRisks:[{min:1,text:"Lower estradiol is the mechanism and the problem: joint aches, low libido and, over a year, spine bone loss (Burnett-Bowie 2009)."}]}},{id:"tamoxifen",name:"Tamoxifen (off-label in men)",category:"prescription",rx:!0,evidence:"moderate",status:"Prescription only; approved for breast cancer, used off-label in men for gynecomastia and infertility. WADA prohibited (S4.2).",summary:"The only PLACEBO-CONTROLLED testosterone rise in men whose levels were already normal: 490 → 790 ng/dL (+61%) against 530 → 560 on placebo, in eugonadal infertile men. Clomiphene does more in the same population, but without a placebo arm. Nobody has ever measured muscle on tamoxifen in men, so the lean number here is an extrapolation whose range starts at zero.",mechanism:"A selective estrogen receptor modulator, like clomiphene: blocks estrogen feedback at the hypothalamus and pituitary.",effects:["Krause 1992 (randomized, placebo-controlled, 76 eugonadal infertile men): testosterone 490 → 790 ng/dL (+61%) versus 530 → 560 on placebo. LH did not differ significantly between groups.","A Cochrane review of 10 trials in 738 men found anti-estrogens improved hormone levels but did not improve pregnancy rates (OR 1.26, 95% CI 0.99–1.56).","Body composition: never measured on tamoxifen in men."],risks:["Venous thromboembolism (blood clots) is the serious one, along with rare ocular effects.","Hot flushes, mood changes, nausea.","Using a breast-cancer drug to raise hormones in a healthy man has no outcome data behind it."],typicalUse:"Off-label, physician-prescribed and monitored, usually for gynecomastia or male infertility.",sources:["Krause W, Holland-Moritz H, Schramm P. Treatment of idiopathic oligozoospermia with tamoxifen: a randomized controlled study. Int J Androl. 1992;15(1):14-18.","Vandekerckhove P, et al. Clomiphene or tamoxifen for idiopathic oligo/asthenospermia. Cochrane Database Syst Rev. 2000;(2):CD000151.","Kadioglu TC, et al. Treatment of idiopathic and postvaricocelectomy oligozoospermia with oral tamoxifen citrate. Int Urol Nephrol. 2009;41(4):773-776.",e],model:{kind:"tEndogenous",dose:{unit:"% of the studied regimen",default:100,label:"as studied (prescriber-set dose)",studied:[0,100]},response:[[0,0],[100,1]],tPctByBaseline:[[150,200],[250,120],[350,86],[450,67],[490,61],[550,55],[650,46],[800,37],[1e3,28]],rampWeeks:6,maxLevel:790,axis:"serm",ceilingNg:790,tCI:[.5,1.5],gate:{secondaryOnly:!0},e2Pct:60,e2ActionPct:0,shbgDelta:0,e2Note:"Serum estradiol rises as on any SERM, but tamoxifen also blocks the receptor in several tissues, so whether estrogen action goes up or down in fat is unknown. Forge models no fat effect either way.",shbgNote:"SHBG did not change significantly in Krause 1992.",tolerability:{grade:"unknown",comparedWith:"nothing — no trial has tabulated adverse events for tamoxifen used this way in men",evidence:"none",headline:"No adverse-event data for this use. The known risks come from the breast-cancer label, in women, at doses and durations that are not comparable.",discontinuation:null,events:[{label:"Venous thromboembolism",pct:null,n:null,of:null,arm:"the established serious risk of tamoxifen, from the oncology literature in women",p:"not quantified in any trial of men using it to raise testosterone; this is the risk that distinguishes tamoxifen from clomiphene on paper",source:"drug label; no male off-label data"},{label:"Hot flushes, mood changes, nausea, ocular effects",pct:null,n:null,of:null,arm:"reported in the oncology population",p:"rates in a eugonadal man taking 20–30 mg for 6 months are unknown",source:"drug label"}],note:`Krause 1992 is the trial Forge's testosterone curve rests on and it reported hormones, not an adverse-event table. Grading this "good" because nothing bad was reported would be reading silence as safety, which is the error this field exists to prevent. The VTE risk is real enough to be on every tamoxifen label, and nobody has measured what it is in this population.`,sources:["Krause W, Holland-Moritz H, Schramm P. Int J Androl. 1992;15(1):14-18. doi:10.1111/j.1365-2605.1992.tb01110.x"]},interactions:[{with:"Strong CYP2D6 inhibitors (paroxetine, fluoxetine, bupropion, quinidine)",kind:"pharmacokinetic",text:"The one genuinely important pharmacokinetic interaction in this whole category. Tamoxifen is a PRODRUG: CYP2D6 converts it to endoxifen, the metabolite with roughly 100-fold greater affinity for the estrogen receptor. Strong CYP2D6 inhibitors severely impair that conversion, and poor-metaboliser CYP2D6 genotypes do the same thing genetically (Brauch 2009, Clin Chem 55:1770-82, doi:10.1373/clinchem.2008.121756). Several very common antidepressants are on that list."},{with:"Anticoagulants (warfarin)",kind:"pharmacokinetic",text:"Tamoxifen potentiates warfarin and the combination is contraindicated on the drug label. This is a prescriber-level interaction, not a thing to manage yourself."},{with:"Aromatase inhibitors and the other SERMs",kind:"pharmacodynamic",text:"Shared lever, so no additive testosterone effect."}],unknowns:["Body composition on tamoxifen in men: never measured, at any baseline.","Whether its tissue-selectivity profile matters for muscle. Tamoxifen is an estrogen antagonist in some tissues and an agonist in others, and which of those applies in skeletal muscle and bone in men is not established.","Thromboembolic risk in healthy men taking it off-label for this purpose. The elevated risk is established in the breast-cancer populations it was studied in; the absolute risk in a healthy 40-year-old man is unquantified.","Long-term use in men for this indication: no trial beyond 6 months (Krause 1992)."],bodyComp:"extrapolated",bcMaxLevel:790,bcNote:"EXTRAPOLATED: nobody has ever measured body composition on tamoxifen in men. Krause 1992 is the only PLACEBO-CONTROLLED testosterone rise in men who were not hypogonadal (490 → 790 ng/dL vs 530 → 560 on placebo, 30 mg/day, 6 months, n=39 vs 37), so Forge runs it through the Bhasin curve and stops at 790. The lower end of the range is zero, because zero is what has actually been measured — and because that curve was built on testosterone given from outside, not made by your own testes.",monitor:["Total testosterone and estradiol","Any leg swelling, chest pain or breathlessness: venous thromboembolism is the serious risk","Eye symptoms","Liver panel"],fertility:"Used for male infertility; hormones improve but a Cochrane review found no improvement in pregnancy rates (OR 1.26, 95% CI 0.99–1.56).",timeCourse:"Krause 1992 ran 6 months.",wada:"WADA prohibited at all times, S4.2.",suits:"Gynecomastia or male infertility, under a prescriber. It is the only item here with a randomized testosterone rise in eugonadal men.",notSuits:"Using a breast-cancer drug for body composition in a healthy man, on an extrapolation and a clot risk, is a bad trade. Absolutely not with any history of thrombosis."}},{id:"cabergoline",name:"Cabergoline (only for high prolactin)",category:"prescription",rx:!0,evidence:"moderate",status:"Prescription only; FDA approved for hyperprolactinemia. Irrelevant unless your prolactin is actually high.",summary:"If high prolactin is what is suppressing your testosterone, treating it fixes the cause. Testosterone normalized in about 61% of men with a prolactinoma within 6 months. If your prolactin is normal, this does nothing and Forge models nothing.",mechanism:"A dopamine agonist that suppresses prolactin secretion. High prolactin blocks GnRH pulses, so lowering it lets LH and testosterone recover.",effects:["Colao 2004 (prospective, 51 men with prolactinoma, 24 months): prolactin normalized in 76–80% and tumour size shrank about 73%; testosterone normalized in 61% by 6 months, and 20 of 51 men still needed hormone replacement.","Sperm volume and count normalized in everyone whose testosterone normalized.","Forge applies an effect only if you enter a prolactin above 20 ng/mL together with a low testosterone."],risks:["Nausea, dizziness, low blood pressure on standing; valvular heart effects at the much higher doses used in Parkinson's disease.","Side effects occurred in about 4.5% of men in the trial."],typicalUse:"Prescribed and monitored by an endocrinologist for confirmed hyperprolactinemia, after looking for the cause (medications, pituitary imaging).",sources:["Colao A, et al. Prolactinomas in men: effect of 2 years of normalization of serum prolactin on bone density and other clinical features. J Clin Endocrinol Metab. 2004;89(4):1704-1711. doi:10.1210/jc.2003-030979","Melmed S, et al. Diagnosis and treatment of hyperprolactinemia: an Endocrine Society clinical practice guideline. J Clin Endocrinol Metab. 2011;96(2):273-288. doi:10.1210/jc.2010-1692 — the guideline that sets out when a raised prolactin is worth treating at all, and how to tell a drug-induced rise from a tumour.","Webster J, et al. A comparison of cabergoline and bromocriptine in the treatment of hyperprolactinemic amenorrhea. N Engl J Med. 1994;331(14):904-909. doi:10.1056/NEJM199410063311403 — the randomized trial (459 patients, double-blind for 8 weeks) that made cabergoline first-line: stable normoprolactinemia in 83% vs 59% (p<0.001), and 3% vs 12% stopping for intolerance (p<0.001). Women, because that is the population it was developed in."],model:{kind:"tEndogenous",dose:{unit:"% of the studied regimen",default:100,label:"as studied (prescriber-set dose)",studied:[0,100]},response:[[0,0],[100,1]],tPctByBaseline:[[150,180],[250,100],[350,45],[450,20],[550,8],[700,0]],rampWeeks:12,maxLevel:900,axis:"dopamine",ceilingNg:900,tCI:[.5,1.5],e2Pct:0,e2ActionPct:0,shbgDelta:0,tolerability:{grade:"good",comparedWith:"its own approved label and the 51-man prospective series; no head-to-head against anything here",evidence:"observational",headline:"Side effects in about 4.5% of men over 2 years, and it is the only item in this group approved for the condition it is treating.",discontinuation:null,events:[{label:"Any side effect",pct:null,n:null,of:51,arm:"reported as about 4.5% over 24 months of treatment for prolactinoma; the paper does not give the numerator, so the underlying count is unknown",source:"Colao 2004"},{label:"Nausea, dizziness, postural hypotension",pct:null,n:null,of:null,arm:"the common label effects, usually at the start of treatment",source:"drug label"},{label:"Cardiac valve disease",pct:null,n:null,of:null,arm:"a known risk of ergot dopamine agonists at the much higher doses used in Parkinson's disease; not seen at hyperprolactinaemia doses",p:"the reason an echocardiogram appears on the monitoring list only for the high-dose use",source:"drug label"}],note:"This grade only means anything for a man who actually has a high prolactin. For everyone else the item is modeled at zero, so its tolerability is not a trade-off he is making.",sources:["Colao A, et al. J Clin Endocrinol Metab. 2004;89(4):1704-1711."]},interactions:[{with:"Dopamine antagonists (antipsychotics, metoclopramide, domperidone)",kind:"pharmacodynamic",text:"Direct opposition: cabergoline works as a dopamine agonist at the pituitary, and these block the same receptor. They are also themselves among the commonest causes of a raised prolactin in the first place — so if one of them is the reason prolactin is high, the conversation to have is about that medicine, not about adding a second one."},{with:"Blood-pressure medicines",kind:"additive",text:"Dopamine agonists can lower blood pressure, particularly on the first doses."},{with:"The SERMs and hCG",kind:"pharmacodynamic",text:"A different mechanism (fixing a specific cause) rather than a shared lever, which is why Forge models it as raising the baseline the other drugs then work from rather than competing with them. It does nothing at all unless prolactin is actually high."}],unknowns:["Body composition: never measured on cabergoline in men, at any prolactin level.","Everything about it in men whose prolactin is normal. There is nothing to treat, no trial has looked, and Forge models zero.","The valve disease signal comes from the much higher doses used in Parkinson’s disease; whether the low prolactin-level doses carry any of that risk is still debated and is the reason echocardiographic monitoring is sometimes advised."],bodyComp:"extrapolated",bcMaxLevel:700,bcNote:"EXTRAPOLATED: Colao 2004 measured bone density, not body composition. Forge runs the restored testosterone through the Bhasin curve and stops at 700 ng/dL, roughly the normal range the responders reached. 39% of men did NOT normalize and still needed replacement.",monitor:["Prolactin (repeat it before acting — one high value is not a diagnosis)","Total testosterone","Pituitary MRI if prolactin is confirmed high","Echocardiogram only at the much higher Parkinson's doses"],fertility:"Sperm volume and count normalized in everyone whose testosterone normalized (Colao 2004).",timeCourse:"Testosterone normalized in ~61% by 6 months.",wada:"Not prohibited.",suits:"A confirmed high prolactin with low testosterone. This treats the cause rather than pushing the axis.",notSuits:"A normal prolactin — then there is nothing here to treat and Forge models zero. A normal testosterone with a high prolactin also gets little or nothing: this gives back what prolactin took, and if nothing was taken there is nothing to give.",gate:{highProlactin:!0,secondaryOnly:!0}}},{id:"nasal_t",name:"Short-acting nasal testosterone (Natesto)",category:"prescription",rx:!0,exogenousT:!0,evidence:"weak",status:"Prescription only (FDA approved as testosterone replacement). This IS exogenous testosterone — it suppresses your own axis, just less than other routes. Using it specifically to protect fertility is off-label. WADA prohibited.",summary:"Testosterone from outside, but dosed so briefly that LH and FSH mostly survive. In a single-arm study, 91% of men reached a normal level while FSH stayed normal in 82% and sperm counts held up — the usual trade-off between testosterone therapy and fertility, partly avoided. It is still exogenous testosterone: suppression is reduced, not eliminated.",mechanism:"Three short nasal doses a day produce brief testosterone peaks instead of a steady level, which seems to leave the pituitary enough unsuppressed time to keep signalling the testes.",effects:["Ramasamy 2020 (open-label, single-arm, 6 months, 33–44 evaluable men): 90.9% reached total T above 300 ng/dL; LH stayed normal in 72.7% and FSH in 81.8%; sperm counts above 5 million were maintained in 93.9% at 6 months.","No control group, significant dropout, and no data beyond 6 months.",'Body composition was not measured. If you use it, enter your measured level under "total T on therapy" and Forge will model it with the testosterone curve.'],risks:["Nasal irritation, runny nose, headache.","It is still exogenous testosterone: suppression is reduced, not eliminated, and the fertility claim rests on one uncontrolled study.","Three-times-daily dosing is easy to miss."],typicalUse:"Prescribed and monitored like any testosterone therapy, sometimes chosen by men who want to protect fertility.",sources:["Ramasamy R, et al. Testosterone nasal gel (Natesto) maintains semen parameters and gonadotropin levels in hypogonadal men: a single-center, open-label study. J Urol. 2020;204(3):557-563.","Bhasin S, et al. Testosterone therapy in men with hypogonadism: an Endocrine Society clinical practice guideline. J Clin Endocrinol Metab. 2018;103(5):1715-1744.",e],model:{kind:"exogenousT",axis:"exogenous",suppresses:!0,axisPreservedPct:75,trialLevel:500,trialLevelNote:'Ramasamy 2020 reported the proportion above 300 ng/dL (90.9%), not a group mean. 500 ng/dL is an ASSUMPTION standing in for "mid-normal", used only when you enter no lab.',bodyComp:"extrapolated",bcMaxLevel:1100,bcNote:"EXTRAPOLATED: body composition was not measured. Enter your measured level and the Bhasin testosterone curve handles it like any other exogenous testosterone.",monitor:["Total testosterone (timing matters — it peaks and falls within the hour)","LH and FSH","Semen analysis if fertility matters","Hematocrit, PSA"],fertility:"The distinguishing claim: LH stayed normal in 72.7% and FSH in 81.8%, and 93.9% kept sperm above 5 million at 6 months (Ramasamy 2020) — but that is one uncontrolled single-arm study with heavy attrition and nothing past 6 months.",timeCourse:"Three doses a day; peaks within ~1 h.",wada:"WADA prohibited at all times, S1 (anabolic androgenic steroids).",suits:"A man who needs testosterone replacement and wants to keep sperm production, who will not miss three doses a day.",notSuits:"Anyone relying on the fertility claim as if it were proven, and anyone who wants to raise their OWN production — this replaces it.",note:"Exogenous testosterone: enter your measured on-therapy level and add Testosterone to your stack; the testosterone curve handles it."}},{id:"oral_tu",name:"Oral testosterone undecanoate (Jatenzo, Tlando, Kyzatrex)",category:"prescription",rx:!0,exogenousT:!0,evidence:"moderate",status:"Prescription only (Schedule III), FDA approved as testosterone replacement. This IS exogenous testosterone: it suppresses your own production and sperm count like any other route. Boxed warning for blood-pressure increases. WADA prohibited.",summary:"Testosterone in a capsule. Three approved products get about 87–88% of hypogonadal men into the normal range without injections or gel transfer — but they are replacement, not restoration: your own axis shuts down, fertility suffers, and all three raise blood pressure. No trial has measured body composition on any of them.",mechanism:"Testosterone undecanoate in a lipid vehicle is absorbed through the intestinal lymphatics with food, bypassing the first-pass liver metabolism that made old oral testosterone hepatotoxic. Serum levels peak and trough within the day, so dosing is twice daily with meals.",effects:["Jatenzo (Swerdloff 2020, phase 3, 166 men vs 56 topical): 87% reached a 24-hour average in the eugonadal range; plasma Cavg 403 ± 128 ng/dL (serum-equivalent ≈489 ± 155), versus 391 ± 140 for topical testosterone.","Jatenzo at 2 years (Honig 2022, 69 men completing 24 months): mean total T 617 ± 427 ng/dL, sexual-function scores improved, no clinically significant liver changes — and HDL fell 9.8 ± 0.9 mg/dL, systolic BP rose 3–6 mmHg.","Tlando (Miner 2024, phase 3, 315 men, baseline 205.7 ± 71.6 ng/dL, 225 mg twice daily): 87.4% within 300–1,140 ng/dL, with no dose titration needed in most.","Tlando blood pressure (White 2021, 138 men, ambulatory monitoring): 24-hour systolic +3.8 mmHg (p<0.001), hematocrit +3.2% and haemoglobin +0.9 g/dL. The men whose hematocrit rose more than 6% had the largest blood-pressure rise (mean +8.3 mmHg).","Kyzatrex (phase 3, 155 men with T ≤281 ng/dL): 88% (95% CI 82–93) reached a 24-hour average of 222–800 ng/dL at day 90; boxed warning for blood pressure.","Body composition was not measured in any of these trials. Forge treats it as exogenous testosterone: enter your measured level and the Bhasin curve applies, labelled an extrapolation."],risks:["Boxed warning: it raises blood pressure, which raises cardiovascular risk. Blood pressure must be controlled before starting and monitored on it.","It suppresses your own testosterone and sperm production like any exogenous testosterone. Not for a man planning fertility soon.","Hematocrit rises (needs regular blood counts); HDL falls.","Must be taken with food twice daily or absorption fails; levels swing within the day, so lab timing matters."],typicalUse:"Physician-prescribed replacement, taken twice daily with meals and titrated on a timed blood level.",sources:["Swerdloff RS, et al. A new oral testosterone undecanoate formulation restores testosterone to normal concentrations in hypogonadal men. J Clin Endocrinol Metab. 2020;105(8):2515-2531. doi:10.1210/clinem/dgaa238","Honig S, et al. Two-year analysis of a new oral testosterone undecanoate (TU) formulation in hypogonadal men: efficacy, impact on psychosexual function, and safety. J Sex Med. 2022;19(12):1750-1758. doi:10.1016/j.jsxm.2022.09.002","Miner M, et al. Safety, efficacy, and pharmacokinetics of oral testosterone undecanoate in males with hypogonadism. Andrology. 2025;13(4):882-893. doi:10.1111/andr.13747","White WB, et al. Effects of a novel oral testosterone undecanoate on ambulatory blood pressure in hypogonadal men. J Cardiovasc Pharmacol Ther. 2021;26(6):630-637. doi:10.1177/10742484211027394","U.S. FDA. KYZATREX (testosterone undecanoate) capsules, prescribing information. Marius Pharmaceuticals; approved July 2022.",e],model:{kind:"exogenousT",axis:"exogenous",suppresses:!0,axisPreservedPct:0,trialLevel:500,trialLevelNote:"Mid-point of the reported on-treatment means (Jatenzo Cavg ≈489 ng/dL serum-equivalent at 3–4 months, 617 at 2 years). Used only when you enter no lab.",bodyComp:"extrapolated",bcMaxLevel:1100,bcNote:"EXTRAPOLATED: no oral testosterone undecanoate trial measured body composition. Enter your measured level and the Bhasin curve applies, as for any exogenous testosterone.",monitor:["Blood pressure (boxed warning) before and during","Total testosterone, timed per the product label","Hematocrit","Lipids (HDL falls)","PSA"],fertility:"Suppressed, like any exogenous testosterone. If fertility matters, the SERMs, hCG or nasal testosterone exist for that reason.",timeCourse:"Levels are in range within days; the trials ran 3–24 months.",wada:"WADA prohibited at all times, S1.",suits:"A man who needs replacement, has a diagnosis, and wants to avoid needles and gel transfer to family.",notSuits:"Anyone trying to raise their OWN testosterone (this replaces it), anyone with uncontrolled blood pressure, and anyone planning children.",note:"Exogenous testosterone: enter your measured level and add Testosterone to your stack; the testosterone curve handles it."}},{id:"pulsatile_gnrh",name:"Pulsatile GnRH (gonadorelin pump)",category:"prescription",rx:!0,evidence:"moderate",status:"Specialist use for congenital hypogonadotropic hypogonadism; not a therapy for otherwise healthy men. US availability is unclear (the approved products were discontinued).",summary:"A pump delivering GnRH in pulses can restart the axis in men born without it. It is not a muscle-building option, and in head-to-head data it produces LOWER testosterone than hCG. Continuous rather than pulsed delivery does the opposite and shuts the axis down.",mechanism:"The pituitary only responds to GnRH arriving in pulses. Pulsed delivery restores LH and FSH; steady delivery desensitizes the receptors and suppresses them, which is how prostate-cancer drugs work.",effects:["Mao 2017 (202 men with congenital hypogonadotropic hypogonadism): pulsatile GnRH gave testosterone of 239 ng/dL versus 467 on hCG/hMG (p<0.001), but sperm appeared much sooner (median 6 vs 18 months).","Wei 2020 meta-analysis (7 studies, 420 men): larger testicular volume and spermatogenesis about 5 months earlier than with gonadotropins; pregnancy rates not significantly different.","No trial has tested it in men with normal pituitary function, so Forge models no effect."],risks:["Wearing an infusion pump continuously; allergic and site reactions.","Continuous (non-pulsed) dosing suppresses testosterone instead of raising it."],typicalUse:"Endocrinologist-supervised treatment for congenital hypogonadotropic hypogonadism, usually when fertility is the goal.",sources:["Mao JF, et al. Pulsatile gonadotropin-releasing hormone therapy is associated with earlier spermatogenesis compared to combined gonadotropin therapy in patients with congenital hypogonadotropic hypogonadism. Asian J Androl. 2017;19(6):680-685.","Wei C, et al. Pulsatile gonadotropin-releasing hormone therapy versus gonadotropin therapy for congenital hypogonadotropic hypogonadism: a systematic review and meta-analysis. World J Mens Health. 2021;39(4):654-665.","Pitteloud N, Dwyer A. Hormonal control of spermatogenesis in men: therapeutic aspects in hypogonadotropic hypogonadism. Ann Endocrinol. 2014;75(2):98-100."],model:{kind:"none",note:"Only studied in congenital hypogonadotropic hypogonadism, where it gives lower testosterone than hCG."}}],n=[{id:"hgh",name:"Growth hormone (HGH / somatropin)",category:"prescription",rx:!0,evidence:"moderate",status:"Prescription only for diagnosed GH deficiency and a few specific conditions; distributing it for anti-aging or bodybuilding is illegal in the US. WADA prohibited.",summary:`In healthy adults, GH increases "lean mass" by ~2 kg, but that's mostly retained water. Strength doesn't improve. Fat mass drops a little. Side effects (swelling, joint pain, carpal tunnel, higher blood sugar) are common.`,mechanism:"Raises IGF-1, promotes fat breakdown and causes sodium and water retention in tissues.",effects:["Healthy young adults (Liu 2008): lean body mass +2.1 kg, no strength gain; much of it fluid.","Healthy older adults (Liu 2007): lean +2.1 kg, fat −2.1 kg over ~6 months.","Forge: water up to +4 lb (not counted as muscle), fat about −0.17 lb/week for the ~26 studied weeks, then no further change."],risks:["Fluid retention and swelling, joint pain, carpal tunnel syndrome, gynecomastia.","Insulin resistance and higher blood sugar (watch HbA1c).","Counterfeit product is common outside prescriptions."],typicalUse:"Only for diagnosed adult GH deficiency, prescribed and monitored by an endocrinologist (dose titrated to IGF-1)",sources:["Liu H, et al. Systematic review: the effects of growth hormone on athletic performance. Ann Intern Med. 2008;148(10):747-758.","Liu H, et al. Systematic review: the safety and efficacy of growth hormone in the healthy elderly. Ann Intern Med. 2007;146(2):104-115.","Molitch ME, et al. Evaluation and treatment of adult growth hormone deficiency: an Endocrine Society clinical practice guideline. J Clin Endocrinol Metab. 2011;96(6):1587-1609.",'Perls TT, Reisman NR, Olshansky SJ. Provision or distribution of growth hormone for "antiaging": clinical and legal issues. JAMA. 2005;294(16):2086-2090.'],model:{kind:"generic",dose:{unit:"mg/day",default:1,label:"within the studied range (healthy-adult trials)",studied:[.2,3]},response:[[0,0],[.3,.4],[1,1]],waterLb:4,fatDirectLbPerWeek:-.17,rampWeeks:3,waterRampWeeks:2,taperAfterWeeks:26,taperTauWeeks:0,levelRisks:[{min:1,text:"At and above ~1 mg/day in healthy adults: swelling, joint pain and carpal tunnel are frequent (Liu 2007/2008), and higher doses added side effects, not benefit."}]}},{id:"tesamorelin",name:"Tesamorelin (Egrifta)",category:"peptide",rx:!0,evidence:"moderate",status:"Prescription only (FDA approved as Egrifta solely for HIV-associated abdominal fat). WADA prohibited.",summary:"A GHRH analog that cut visceral (deep belly) fat by ~15% over 26 weeks in people with HIV lipodystrophy. Evidence in healthy lifters is lacking; the modeled effect is tiny.",mechanism:"Stimulates the pituitary to release more of your own GH, raising IGF-1.",effects:["Visceral fat about −15% over 26 weeks (HIV lipodystrophy trials).","Forge: fat about −0.03 lb/week for the 26 studied weeks."],risks:["Joint pain, swelling, injection-site reactions; higher blood sugar."],typicalUse:"Only for HIV-associated abdominal fat accumulation, as prescribed",sources:["Falutz J, et al. Metabolic effects of a growth hormone-releasing factor in patients with HIV. N Engl J Med. 2007;357(23):2359-2370.","Stanley TL, et al. Effect of tesamorelin on visceral fat and liver fat in HIV-infected patients with abdominal fat accumulation: a randomized clinical trial. JAMA. 2014;312(4):380-389."],model:{kind:"generic",dose:{unit:"mg/day",default:2,label:"studied dose",studied:[1,2]},response:[[0,0],[1,.6],[2,1]],fatDirectLbPerWeek:-.03,rampWeeks:4,taperAfterWeeks:26,taperTauWeeks:0}},{id:"kisspeptin",name:"Kisspeptin and kisspeptin analogs (MVT-602, TAK-448)",category:"peptide",rx:!0,evidence:"refuted",status:`Investigational research peptides; none is approved anywhere. Kisspeptin-10 is in Category 2 of FDA's 503A bulk-substances list — substances that raise significant safety risks, which Category 1's enforcement discretion does not cover (list updated 14 May 2026). WADA prohibited at all times in males: "kisspeptin and its agonist analogues" is named explicitly under S2.2.1, testosterone-stimulating peptides (Prohibited List 2026).`,summary:"The most upstream switch in the whole axis, and the human trials are a cautionary tale. A single infusion raises testosterone 15–45% for a few hours, but when the long-acting analogs were given continuously, testosterone fell BELOW castrate levels within a week. There is no way to use this to raise testosterone long-term.",mechanism:"Kisspeptin neurons drive the GnRH pulse generator. Pulses stimulate it; continuous exposure desensitizes the receptor, which is exactly how the analogs were being developed as prostate-cancer drugs.",effects:["Dhillo 2005 (6 healthy men, 90-minute IV infusion): mean testosterone 718 vs 626 ng/dL on placebo, about +15%. Half-life 28 minutes.","George 2011 (healthy men, 22.5-hour infusion, n=4): 479 → 692 ng/dL (+45%), with tachyphylaxis already visible at the higher bolus dose.","George 2013 (5 men with type 2 diabetes and low testosterone, 11-hour infusion): 245 → 329 ng/dL (+34%).","MacLean 2014 (TAK-448, phase 1): a single dose raised T only 1.3–2 fold, and 14 days of continuous infusion put men below castrate levels by day 8.","Scott 2013 (TAK-448, phase 1, 60 + 30 healthy men): at the top continuous dose, testosterone fell below 50 ng/dL in 4 of 5 men by day 7.","MVT-602 has published human data only in women; no male testosterone data exist. No chronic, muscle or body-composition data for any of these."],risks:["Continuous dosing suppresses testosterone rather than raising it — the opposite of the intent.","IV infusions only; no practical dosing route exists for the native peptides.","Unregulated research-chemical products: contents, purity and sterility are not verified."],typicalUse:null,sources:["Dhillo WS, et al. Kisspeptin-54 stimulates the hypothalamic-pituitary-gonadal axis in human males. J Clin Endocrinol Metab. 2005;90(12):6609-6615.","George JT, et al. Kisspeptin-10 is a potent stimulator of LH and increases pulse frequency in men. J Clin Endocrinol Metab. 2011;96(8):E1228-E1236.","George JT, et al. Kisspeptin-10 stimulation of gonadotrophin secretion in women and men with type 2 diabetes. Clin Endocrinol. 2013;79(1):100-104.","MacLean DB, et al. Sustained exposure to the investigational kisspeptin analog TAK-448 down-regulates testosterone into the castration range in healthy males and in patients with prostate cancer. J Clin Endocrinol Metab. 2014;99(8):E1445-E1453.","Scott G, et al. Pharmacokinetics, pharmacodynamics, safety and tolerability of TAK-448, a novel kisspeptin analogue, in healthy males. Br J Clin Pharmacol. 2013;75(2):381-391.","U.S. FDA. Bulk drug substances that raise significant safety risks (Category 2), updated May 2026."],model:{kind:"none",note:"Acute infusions only; continuous dosing lowers testosterone below castrate levels."}},{id:"leydig_regen",name:"Leydig stem-cell and gene-therapy research",category:"peptide",evidence:"preclinical",status:"Laboratory and animal research only. Nothing is available to patients, and no human trial was verifiable.",summary:"The long-term dream: repair or replace the cells that make testosterone, instead of supplementing it. In 2023 gene-edited stem Leydig cells restored testosterone, puberty and fertility in mice with a genetic receptor defect. In humans, nothing.",mechanism:"Stem Leydig cells, mesenchymal stem cells or iPSC-derived Leydig-like cells are transplanted into the testis to restore steroid production, with gene editing where the defect is genetic.",effects:["Xia 2023 (mice with an Lhcgr nonsense mutation): prime-edited stem Leydig cells regenerated Leydig cells, recovered testosterone, restarted sexual development and produced fertile offspring.","Curley 2019: human fat-derived pericytes switched on steroidogenic genes in a dish but did not become Leydig cells in rats, and were undetectable a month later.","No human serum-testosterone data exist. Forge models nothing."],risks:["Entirely unproven in humans; anything sold on this basis today is a scam."],typicalUse:null,sources:["Xia K, et al. Restorative functions of autologous stem Leydig cell transplantation with prime editing in a mouse model of hypogonadism. Adv Sci. 2023;10(29):e2300993.","Curley M, et al. Human adipose-derived pericytes display steroidogenic lineage potential in vitro but do not generate Leydig cells in vivo. Sci Rep. 2019;9:15037.","Zhu WB, et al. Stem cell-based therapies for testicular aging and Leydig cell dysfunction. Reprod Biol Endocrinol. 2025;23:147."],model:{kind:"none",note:"Animal and cell research only."}},{id:"bpc157",name:"BPC-157",category:"peptide",evidence:"none",status:`Not FDA approved; sold as a research chemical. CORRECTED 2026-10-20: it is NOT on FDA's Category 2 "significant safety risks" list — its compounding nomination was withdrawn, and FDA's safety-risks page lists it among withdrawn nominations with an immunogenicity concern, saying it "lacks sufficient information to know whether the drug would cause harm". WADA prohibited.`,summary:'Popular for "healing" injuries, but every positive result comes from rats or anecdotes. There are no controlled human studies on healing, muscle or fat. Forge projects no effect.',mechanism:"Proposed to promote blood-vessel growth and tendon healing in animal models. Unknown in humans.",effects:["No human body-composition data, so no projected effect."],risks:["Unregulated: purity, dose and sterility of research-chemical vials aren't verified.","Injection risks (infection); unknown long-term effects, including theoretical concerns with angiogenesis and cancer."],typicalUse:null,sources:["Gwyer D, Wragg NM, Wilson SL. Gastric pentadecapeptide body protection compound BPC 157 and its role in accelerating musculoskeletal soft tissue healing. Cell Tissue Res. 2019;377(2):153-159.","Seiwerth S, et al. BPC 157 and standard angiogenic growth factors. Gastrointestinal tract healing, lessons from tendon, ligament, muscle and bone healing. Curr Pharm Des. 2018;24(18):1972-1989.",s,e],model:{kind:"none",note:"No human evidence."}},{id:"tb500",name:"TB-500 (thymosin β4 fragment)",category:"peptide",evidence:"none",status:"Not FDA approved; sold as a research chemical; WADA prohibited.",summary:"Marketed for recovery and healing based on animal and cell research on thymosin β4. There are no human trials on muscle or fat. Forge projects no effect.",mechanism:"Thymosin β4 regulates actin and cell migration in wound healing (lab and animal data).",effects:["No human body-composition data, so no projected effect."],risks:["Unregulated: contents and purity aren't verified.","Unknown long-term safety in humans."],typicalUse:null,sources:["Goldstein AL, Hannappel E, Sosne G, Kleinman HK. Thymosin β4: a multi-functional regenerative peptide. Basic properties and clinical applications. Expert Opin Biol Ther. 2012;12(1):37-51.",e],model:{kind:"none",note:"No human evidence."}},{id:"ipamorelin_cjc",name:"Ipamorelin / CJC-1295",category:"peptide",evidence:"none",status:"Not FDA approved; sold as research chemicals. Ipamorelin acetate is in Category 2 of FDA's 503B bulk-substances list (substances that raise significant safety risks, entry dated 29 September 2023), so outsourcing facilities may not compound from it. WADA prohibited.",summary:"These raise your own GH and IGF-1 (CJC-1295 for days per injection), but there are no good human studies showing more muscle or less fat. Even real GH mostly adds water in healthy adults. Forge projects no effect.",mechanism:"Ipamorelin is a ghrelin-receptor GH secretagogue; CJC-1295 is a long-acting GHRH analog.",effects:["CJC-1295 raised GH 2–10× and IGF-1 1.5–3× in healthy adults (Teichman 2006); body composition was not shown to change.","No projected effect."],risks:["Unregulated vials (purity, dose, sterility).","Flushing, headache, injection-site reactions, water retention and higher blood sugar (GH-axis effects).","CJC-1295 never completed clinical development, so long-term safety is unknown."],typicalUse:null,sources:["Teichman SL, et al. Prolonged stimulation of growth hormone (GH) and insulin-like growth factor I secretion by CJC-1295, a long-acting analog of GH-releasing hormone, in healthy adults. J Clin Endocrinol Metab. 2006;91(3):799-805.","Raun K, et al. Ipamorelin, the first selective growth hormone secretagogue. Eur J Endocrinol. 1998;139(5):552-561.",i,e],model:{kind:"none",note:"Raises GH/IGF-1; no human body-composition data."}},{id:"mk677",name:"MK-677 (ibutamoren)",category:"peptide",evidence:"weak",status:"Not FDA approved; sold as a research chemical. Ibutamoren mesylate is in Category 2 on both of FDA's bulk-substances lists — 503A (updated 14 May 2026) and 503B (dated 29 September 2023) — meaning FDA has identified significant safety risks and neither a pharmacy nor an outsourcing facility has a compounding route for it. WADA prohibited.",summary:"An oral GH secretagogue. In trials, fat-free mass went up 1–3 kg, but mostly as water, with no strength or function benefit. It increases appetite and blood sugar and lowers insulin sensitivity.",mechanism:"Ghrelin-receptor agonist: raises GH and IGF-1 around the clock and increases hunger.",effects:["Older adults, 25 mg/day for 12 months: FFM +1.1 kg vs −0.5 kg placebo, no strength change (Nass 2008).","Obese adults, 8 weeks: FFM +3 kg, fat unchanged (Svensson 1998). Reversed diet-induced protein loss in young men (Murphy 1998).","Forge: water up to +3.3 lb, ~10% better lean retention in a deficit, appetite +150 kcal/day (when intake isn't user-set)."],risks:["Higher fasting glucose and lower insulin sensitivity; check HbA1c.","Increased appetite, swelling, joint pain, numbness.","A hip-fracture trial in elderly patients was stopped over heart-failure cases.","Unregulated products."],typicalUse:null,sources:["Nass R, et al. Effects of an oral ghrelin mimetic on body composition and clinical outcomes in healthy older adults: a randomized trial. Ann Intern Med. 2008;149(9):601-611.","Svensson J, et al. Two-month treatment of obese subjects with the oral growth hormone (GH) secretagogue MK-677 increases GH secretion, fat-free mass, and energy expenditure. J Clin Endocrinol Metab. 1998;83(2):362-369.","Murphy MG, et al. MK-677, an orally active growth hormone secretagogue, reverses diet-induced catabolism. J Clin Endocrinol Metab. 1998;83(2):320-325.","Chapman IM, et al. Stimulation of the growth hormone (GH)-insulin-like growth factor I axis by daily oral administration of a GH secretogogue (MK-677) in healthy elderly subjects. J Clin Endocrinol Metab. 1996;81(12):4249-4257.",e],model:{kind:"generic",dose:{unit:"mg/day",default:25,label:"studied dose",studied:[10,25]},response:[[0,0],[10,.6],[25,1]],waterLb:3.3,leanRetentionMult:.9,intakeDelta:150,rampWeeks:4,waterRampWeeks:3}},{id:"enobosarm",name:"Enobosarm (ostarine, MK-2866), a SARM",category:"peptide",evidence:"weak",status:"Not FDA approved; sold online as a research chemical (often mislabeled); FDA has warned against SARMs; WADA prohibited.",summary:"In phase-2 trials in older adults and cancer patients, about 1.3 kg more lean mass than placebo over ~12 weeks at 3 mg/day. There are no long-term or young-lifter data, and a lot of what's sold online isn't what the label says.",mechanism:"Selective androgen receptor modulator: androgenic signaling in muscle and bone with less effect on prostate (in theory).",effects:["Dalton 2011: total lean mass ≈ +1.3 kg vs placebo at 3 mg/day for 86 days.","Forge: direct lean up to ~0.23 lb/week for the 12 studied weeks, then no further gain."],risks:["Suppresses natural testosterone and lowers HDL cholesterol.","Liver-injury case reports.",'In a JAMA analysis, only about half of online "SARMs" contained what the label said, and many contained other drugs.'],typicalUse:null,sources:["Dalton JT, et al. The selective androgen receptor modulator GTx-024 (enobosarm) improves lean body mass and physical function in healthy elderly men and postmenopausal women: results of a double-blind, placebo-controlled phase II trial. J Cachexia Sarcopenia Muscle. 2011;2(3):153-161.","Dobs AS, et al. Effects of enobosarm on muscle wasting and physical function in patients with cancer: a double-blind, randomised controlled phase 2 trial. Lancet Oncol. 2013;14(4):335-345.","Van Wagoner RM, et al. Chemical composition and labeling of substances marketed as selective androgen receptor modulators and sold via the Internet. JAMA. 2017;318(20):2004-2010.",e],model:{kind:"generic",dose:{unit:"mg/day",default:3,label:"studied dose",studied:[.1,3]},response:[[0,0],[.3,.3],[1,.8],[3,1]],leanDirectLbPerWeek:.23,rampWeeks:0,taperAfterWeeks:12,taperTauWeeks:0}},{id:"lgd4033",name:"LGD-4033 (ligandrol), a SARM",category:"peptide",evidence:"weak",status:"Not FDA approved; sold online as a research chemical (often mislabeled); FDA has warned against SARMs; WADA prohibited.",summary:"One 3-week trial in healthy young men: +1.2 kg lean mass at 1 mg/day, with dose-related drops in testosterone and HDL. Nothing is known beyond 3 weeks, so Forge stops the effect there.",mechanism:"Selective androgen receptor modulator.",effects:["Basaria 2013: lean body mass +1.21 kg at 1.0 mg/day over 21 days; no fat change.","Forge: direct lean only for the 3 studied weeks."],risks:["Dose-dependent suppression of total testosterone, SHBG and HDL within 3 weeks.","Liver-injury case reports.","Online products are frequently mislabeled or contaminated."],typicalUse:null,sources:["Basaria S, et al. The safety, pharmacokinetics, and effects of LGD-4033, a novel nonsteroidal oral, selective androgen receptor modulator, in healthy young men. J Gerontol A Biol Sci Med Sci. 2013;68(1):87-95.","Van Wagoner RM, et al. Chemical composition and labeling of substances marketed as selective androgen receptor modulators and sold via the Internet. JAMA. 2017;318(20):2004-2010.",e],model:{kind:"generic",dose:{unit:"mg/day",default:1,label:"highest studied dose",studied:[.1,1]},response:[[0,0],[.3,.3],[1,1]],leanDirectLbPerWeek:.89,rampWeeks:0,taperAfterWeeks:3,taperTauWeeks:0}}],l=Object.freeze([{before:"semaglutide",items:o},{before:null,items:n}]),d=Object.freeze([...o,...n].map(a=>a.id)),t="A male-hypogonadism therapy (it works by pushing the testes to make more testosterone). In women it is used for other things",h={trt:{status:"Prescription only (Schedule III). There is no US-approved testosterone product for women: the only evidence-based use is low sexual desire after menopause, dosed to premenopausal levels (Davis 2019 consensus). Gender-affirming therapy is specialist care. WADA prohibited.",summary:"In women, lean mass rises with the blood level: about +0.6 kg per +100 ng/dL over 24 weeks in the only dose-response trial (Huang 2014, up to ~210 ng/dL), with no change in fat. At male-range levels (trans men), about +3.9 kg lean and −2.6 kg fat over a year. Forge uses your on-therapy level (or estimates it from your dose) against your own natural level.",mechanism:"Androgen-receptor activation raises muscle protein synthesis. Women normally have about 10–57 ng/dL (Haring 2012), so anything above that is supraphysiologic for a woman.",effects:["Huang 2014 (71 hysterectomized women, 24 weeks, no training): testosterone enanthate 3 / 6.25 / 12.5 / 25 mg/week → nadir ≈78 / 102 / 128 / 210 ng/dL; lean mass +0.6 kg per +100 ng/dL (95% CI 0.2–1.1), only 25 mg beat placebo (+1.8 kg); no fat change at any dose; chest-press and stair-climb power rose at 25 mg.","Physiological doses (Islam 2019 meta-analysis, 36 RCTs, 8,480 women): no effect on body composition or muscle; more acne and hair growth.","Trans men on male-range testosterone for ~1 year: lean +3.9 kg and fat −2.6 kg (Klaver 2016 meta-analysis), muscle +10.4% (Van Caenegem 2015), thigh muscle +15% (Wiik 2020). Grip gains were the same across levels from ~288 to ~1,555 ng/dL (Scharff 2019).","Forge (women): lean asymptote linear in serum T above your own level (Huang's slope), flat above ~600 ng/dL; fat change only above ~230 ng/dL; training ceiling unchanged (no study of testosterone × training in women); the reachable FFMI ceiling rises by the lean mass it adds."],risks:["Above the female range: acne and more body and facial hair (hair score rose at 12.5–25 mg/week in Huang 2014; Islam 2019).","Male-range levels (as in gender-affirming therapy): voice deepening and clitoral enlargement, which can be permanent; periods usually stop; hematocrit rises into the male range (Endocrine Society guideline, Hembree 2017).","Contraindicated in pregnancy: it can virilize a female fetus.","If prescribed: total T at baseline, after 3–6 weeks and every 6 months; stop if there is no benefit by 6 months; pellets, injections and supraphysiologic doses are not recommended for women (Davis 2019)."],typicalUse:"Women: only for postmenopausal low sexual desire (HSDD), transdermal, dosed to premenopausal levels (Davis 2019). Gender-affirming therapy under specialist care.",sources:["Huang G, et al. Testosterone dose-response relationships in hysterectomized women with or without oophorectomy: effects on sexual function, body composition, muscle performance and physical function in a randomized trial. Menopause. 2014;21(6):612-623. doi:10.1097/GME.0000000000000093","Huang G, et al. Testosterone dose-response relationships with cardiovascular risk markers in androgen-deficient women: a randomized, placebo-controlled trial. J Clin Endocrinol Metab. 2014;99(7):E1287-E1293. doi:10.1210/jc.2013-4160","Klaver M, et al. Cross-sex hormone therapy in transgender persons affects total body weight, body fat and lean body mass: a meta-analysis. Andrologia. 2017;49(5):e12660. doi:10.1111/and.12660","Van Caenegem E, et al. Body composition, bone turnover, and bone mass in trans men during testosterone treatment: 1-year follow-up data from a prospective case-controlled study (ENIGI). Eur J Endocrinol. 2015;172(2):163-171. doi:10.1530/EJE-14-0586","Wiik A, et al. Muscle strength, size, and composition following 12 months of gender-affirming treatment in transgender individuals. J Clin Endocrinol Metab. 2020;105(3). doi:10.1210/clinem/dgz247","Scharff M, et al. Change in grip strength in trans people and its association with lean body mass and bone density. Endocr Connect. 2019;8(7):1020-1028. doi:10.1530/EC-19-0196","Islam RM, et al. Safety and efficacy of testosterone for women: a systematic review and meta-analysis of randomised controlled trial data. Lancet Diabetes Endocrinol. 2019;7(10):754-766. doi:10.1016/S2213-8587(19)30189-5","Davis SR, et al. Global consensus position statement on the use of testosterone therapy for women. J Clin Endocrinol Metab. 2019;104(10):4660-4666. doi:10.1210/jc.2019-01603","Wierman ME, et al. Androgen therapy in women: a reappraisal: an Endocrine Society clinical practice guideline. J Clin Endocrinol Metab. 2014;99(10):3489-3510. doi:10.1210/jc.2014-2260","Hembree WC, et al. Endocrine treatment of gender-dysphoric/gender-incongruent persons: an Endocrine Society clinical practice guideline. J Clin Endocrinol Metab. 2017;102(11):3869-3903. doi:10.1210/jc.2017-01658","Haring R, et al. Age-specific reference ranges for serum testosterone and androstenedione concentrations in women measured by liquid chromatography-tandem mass spectrometry. J Clin Endocrinol Metab. 2012;97(2):408-415. doi:10.1210/jc.2011-2134"],model:{dose:{unit:"mg/week",default:3,label:"lowest dose in the female dose-response trial (Huang 2014)",studied:[3,25],note:"Testosterone enanthate. Only used to estimate your level when no on-therapy lab is entered; above 25 mg/week Forge uses the men's dose-level data (no larger doses were studied in women)."},doseToLevel:[[0,19],[3,78],[6.25,102],[12.5,128],[25,210],[50,306],[125,542],[300,1345],[600,2370]],leanCeilingMult:1,leanDirectLbPerWeek:.04,fatDirectLbPerWeek:0,levelRisks:[{min:1,text:"Testosterone isn't approved for women in the US; the consensus is to keep levels within the premenopausal range and use it only for postmenopausal low sexual desire (Davis 2019). Never during pregnancy."},{min:60,text:"Above the female range (~57 ng/dL): acne and more body and facial hair become more common (Huang 2014; Islam 2019)."},{min:200,text:"At Huang 2014's top dose (~210 ng/dL) hemoglobin and hematocrit rose with dose (still within the female range); hair growth increased."},{min:300,text:"Male-range level: expect voice deepening and clitoral enlargement that can be permanent, periods stopping, and hematocrit and blood pressure rising toward male values (Hembree 2017). Needs specialist monitoring."}]}},clomiphene:{model:{femaleNote:`${t}: clomiphene is FDA-approved to induce ovulation. It doesn't build muscle in women; Forge models no effect.`}},enclomiphene:{model:{femaleNote:`${t}. It has no muscle or testosterone role in women; Forge models no effect.`}},hcg:{model:{femaleNote:`${t}: hCG triggers ovulation in fertility treatment. Forge models no body-composition effect.`}},aromatase_inhibitor:{model:{femaleNote:`${t}: aromatase inhibitors treat breast cancer and induce ovulation. They lower estrogen, which costs bone. Forge models no muscle effect.`}},tamoxifen:{model:{femaleNote:`${t}: tamoxifen treats and prevents breast cancer. Forge models no muscle effect.`}},cabergoline:{model:{femaleNote:"In women cabergoline treats high prolactin, which restores periods and fertility. That is a health effect, not a muscle effect; Forge models none."}},oral_tu:{status:"Prescription only (Schedule III). Approved for male hypogonadism; there is no approved oral testosterone product for women and the doses are far above the female range. WADA prohibited.",model:{femaleNote:`${t.replace("(it works by pushing the testes to make more testosterone)","(oral testosterone replacement for men)")}. Forge models no effect for women; see Testosterone for the female evidence.`}}},c=[{name:'Other anabolic steroids (trenbolone, nandrolone, oral "stacks")',why:"No dose–response trials in healthy lifters to model from, and liver, heart and lipid risks are serious. (Testosterone itself is modeled from Bhasin's trials.) If you're considering them, talk to a physician."},{name:"Clenbuterol",why:"Not approved for humans in the US. At the doses people use it causes heart-rhythm problems, cardiac damage and deaths, and there's no responsible model."},{name:"DNP (2,4-dinitrophenol)",why:'An industrial chemical that causes fatal overheating; deaths occur even at doses users thought were "safe". Never take it.'},{name:"Insulin (for bodybuilding)",why:"Severe hypoglycemia can kill within hours. It's only safe as diagnosed diabetes care."},{name:"Thyroid hormone for fat loss",why:"In people with normal thyroid function, it burns muscle along with fat and risks atrial fibrillation and bone loss. Treat only diagnosed hypothyroidism."},{name:'Diuretics for "drying out"',why:"Water loss isn't fat loss, and electrolyte shifts can cause dangerous heart rhythms. Forge only models water from creatine and GH-axis compounds."},{name:"Ephedrine / ECA stacks",why:"Banned in US dietary supplements since 2004 after heart attacks, strokes and deaths. The fat-loss effect is small next to the risk."}],m=Object.freeze([{k:"totalT",label:"Total testosterone",why:"The number everything is gated on. Morning (7–10 am), fasted, and repeated on a separate day — it is pulsatile."},{k:"freeT",label:"Free testosterone",why:"Equilibrium dialysis, or calculated from total T and SHBG. Normal total with low free points at high SHBG."},{k:"lh",label:"LH",why:'The single most decisive one. LH is the pituitary’s instruction to your testes. Low T with a normal or low LH means the instruction is not being sent — that is "secondary", and it is what clomiphene, enclomiphene and hCG treat. Low T with a HIGH LH means the instruction is being shouted and not obeyed, so pushing it louder will not help. That second case is NOT something you can tell by looking or feeling: most of a testis is sperm-producing tubules, and the Leydig cells that make testosterone are a small fraction of its volume, so they can be underperforming at a perfectly normal size. In between is "compensated" — LH already raised while testosterone is still normal — a state that becomes more common with age (9.5% of men aged 40–79 in EMAS, Tajar 2010). Forge treats LH as a gradient, not a switch.'},{k:"fsh",label:"FSH",why:"Drawn with LH; together they stage the axis and track fertility."},{k:"estradiol",label:"Estradiol (sensitive assay)",why:"Men need it: it is what keeps fat down (Finkelstein 2013) and bone intact. It decides whether an aromatase inhibitor makes any sense."},{k:"shbg",label:"SHBG",why:"Converts total T into free T, and rises with under-eating and age."},{k:"prolactin",label:"Prolactin",why:"A treatable cause of low testosterone. Cabergoline does nothing unless this is high."},{k:"vitD",label:"25(OH) vitamin D",why:"Correcting a real deficiency helps muscle function a little; supplementing a replete man does nothing."},{k:"ferritin",label:"Ferritin",why:"Commonly low in endurance athletes (hurts training); very high can mean iron overload, a recognised cause of low testosterone."},{k:"zinc",label:"Serum zinc",why:"Only a measured deficiency (<70 µg/dL) moves testosterone."}]);export{c as NOT_MODELED,r as RX_CATEGORY,h as RX_FEMALE,l as RX_INSERTS,d as RX_ITEM_IDS,m as T_LAB_PANEL};
